export const INITIAL_EMPLOYEES: Employee[] = [
  { id: 'e1', name: 'João Silva', sector: Sector.PRODUCTION, active: true },
  { id: 'e2', name: 'Maria Santos', sector: Sector.FINISHING, active: true },
