import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addProductionItems, currentUser, productionItems, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Stats for the day
  const today = new Date().toDateString();
  const todaysProduction = productionItems.filter(p => new Date(p.createdAt).toDateString() === today);
  const dailyTotal = todaysProduction.length;
  // Simplistic earnings calc for production (just showing volume for now as requested in prompt "Ganho diário" implies some value)
  const dailyValue = todaysProduction.reduce((acc, item) => {
    const model = vaseModels.find(v => v.id === item.modelId);
    return acc + (model?.costProduction || 0);
  }, 0);

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const confirmProduction = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const newItems: ProductionItem[] = [];
    const now = Date.now();

    draftItems.forEach(({ model, quantity }) => {
      for (let i = 0; i < quantity; i++) {
        newItems.push({
          id: uuidv4(),
          modelId: model.id,
          modelName: model.name,
          type: model.type,
          status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
          createdAt: now,
          updatedAt: now,
          producedBy: currentUser.id
        });
      }
    });

    addProductionItems(newItems);
    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback(`${newItems.length} itens lançados com sucesso!`);
    setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="p-4 pb-24 max-w-2xl mx-auto">
      {/* Navigation Header */}
      <div className="mb-4">
        <Button variant="ghost" size="sm" onClick={logout} className="pl-0 text-slate-600 dark:text-slate-300 hover:bg-transparent justify-start">
          <ArrowLeft className="mr-2 h-5 w-5" /> Voltar
        </Button>
      </div>

      {/* Header Banner */}
      <Card className="bg-gradient-to-r from-blue-600 to-blue-500 text-white mb-6 p-6">
        <h2 className="text-lg opacity-90 mb-1">Olá, {currentUser?.name}</h2>
        <div className="flex justify-between items-end">
          <div>
            <p className="text-3xl font-bold">{dailyTotal} vasos</p>
            <p className="text-sm opacity-80">Produzidos hoje</p>
          </div>
          <div className="text-right">
             <p className="text-2xl font-bold">R$ {dailyValue.toFixed(2)}</p>
             <p className="text-sm opacity-80">Custo produtivo dia</p>
          </div>
        </div>
      </Card>

      {/* Main Action */}
      <Button size="xl" onClick={() => setIsModalOpen(true)} className="w-full mb-6 shadow-lg">
        <Plus className="w-8 h-8 mr-2" />
        Lançar Produção
      </Button>

      {/* Draft Area Preview */}
      {draftItems.length > 0 && (
        <div className="mb-6">
          <h3 className="text-lg font-bold mb-2 flex items-center text-slate-700 dark:text-slate-200">
             <ClipboardList className="mr-2" /> Rascunho Atual
          </h3>
          <div className="space-y-2">
            {draftItems.map((item) => (
               <Card key={item.model.id} className="flex justify-between items-center py-3 px-4">
                 <span>{item.model.name}</span>
                 <Badge color="blue">{item.quantity} un</Badge>
               </Card>
            ))}
          </div>
        </div>
      )}

      {/* Feedback Snackbar */}
      {feedback && (
        <div className="fixed bottom-4 left-4 right-4 bg-green-600 text-white p-4 rounded-lg shadow-xl z-50 animate-in slide-in-from-bottom">
           <div className="flex items-center">
             <Check className="mr-2" /> {feedback}
           </div>
        </div>
      )}

      {/* Launch Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={selectedType ? `Lançar: ${selectedType}` : "Nova Produção"}
        footer={
          draftItems.length > 0 ? (
            <div className="flex gap-3 w-full">
              <div className="flex-1 text-slate-600 flex items-center justify-center font-bold">
                 Total: {draftItems.reduce((a,b) => a + b.quantity, 0)}
              </div>
              <Button onClick={confirmProduction} className="flex-1">
                Confirmar
              </Button>
            </div>
          ) : undefined
        }
      >
        {!selectedType ? (
          <div className="grid grid-cols-1 gap-4 mt-2">
             <Button size="lg" variant="secondary" onClick={() => setSelectedType(VaseType.WITH_SHELL)}>
                <div className="text-left">
                  <div className="text-lg font-bold">Com Casca</div>
                  <div className="text-sm font-normal opacity-70">Vai para acabamento</div>
                </div>
             </Button>
             <Button size="lg" variant="secondary" onClick={() => setSelectedType(VaseType.WITHOUT_SHELL)}>
                <div className="text-left">
                  <div className="text-lg font-bold">Sem Casca</div>
                  <div className="text-sm font-normal opacity-70">Vai direto p/ estoque</div>
                </div>
             </Button>
          </div>
        ) : (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setSelectedType(null)} className="mb-2">
               ← Trocar Tipo
            </Button>

            <div className="grid gap-3">
              {availableModels.map(model => {
                 const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
                 return (
                   <div key={model.id} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800 border rounded-lg">
                      <div className="flex-1">
                        <div className="font-bold text-lg">{model.name}</div>
                        <div className="text-sm text-slate-500">R$ {model.costProduction.toFixed(2)}</div>
                      </div>

                      <div className="flex items-center gap-3">
                        {inDraft > 0 && (
                          <button onClick={() => removeFromDraft(model.id)} className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center active:bg-slate-300">
                             <Minus className="w-6 h-6" />
                          </button>
                        )}
                        <span className={`w-8 text-center font-bold text-xl ${inDraft > 0 ? 'text-blue-600' : 'text-slate-300'}`}>
                           {inDraft}
                        </span>
                        <button onClick={() => addToDraft(model)} className="w-10 h-10 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center active:bg-blue-200">
                           <Plus className="w-6 h-6" />
                        </button>
                      </div>
                   </div>
                 );
              })}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default ProductionScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { Sector, ItemStatus } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Check, Info, ArrowLeft } from 'lucide-react';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, updateItemStatus, currentUser, logout } = useStore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);

  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    outputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Setor de Acabamento',
    action: 'Enviar para Pintura',
    emptyMsg: 'Nenhum vaso aguardando acabamento.'
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    outputStatus: ItemStatus.FINISHED,
    title: 'Setor de Pintura',
    action: 'Finalizar Vasos',
    emptyMsg: 'Nenhum vaso aguardando pintura.'
  };

  const pendingItems = useMemo(() => 
    productionItems.filter(i => i.status === config.inputStatus)
    .sort((a,b) => b.createdAt - a.createdAt),
  [productionItems, config.inputStatus]);

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleConfirm = () => {
    if (!currentUser) return;
    updateItemStatus(Array.from(selectedIds), config.outputStatus, currentUser.id, stage);
    setSelectedIds(new Set());
    setIsConfirmOpen(false);
  };

  // Group by model for better display? Or list individually? 
  // Prompt says: "Lista automática de vasos... Funcionário seleciona quantos quiser".
  // Let's list individually but maybe visual grouping helps.

  return (
    <div className="p-4 pb-24 max-w-2xl mx-auto">
      <div className="flex items-center mb-4">
        <Button variant="ghost" size="sm" onClick={logout} className="mr-2 -ml-3 text-slate-600 dark:text-slate-300">
           <ArrowLeft className="w-6 h-6" />
        </Button>
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{config.title}</h2>
      </div>

      {pendingItems.length === 0 ? (
        <div className="text-center py-10 opacity-50">
           <Info className="w-12 h-12 mx-auto mb-2" />
           <p>{config.emptyMsg}</p>
        </div>
      ) : (
        <div className="space-y-3">
          {pendingItems.map((item) => {
            const isSelected = selectedIds.has(item.id);
            return (
              <div 
                key={item.id}
                onClick={() => toggleSelect(item.id)}
                className={`
                  relative p-4 rounded-xl border-2 transition-all cursor-pointer flex justify-between items-center
                  ${isSelected ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'border-transparent bg-white dark:bg-slate-800 shadow-sm'}
                `}
              >
                <div>
                   <p className="font-bold text-lg">{item.modelName}</p>
                   <p className="text-xs text-slate-500">ID: {item.id.slice(0, 8)}</p>
                </div>

                <div className={`
                   w-8 h-8 rounded-full border-2 flex items-center justify-center
                   ${isSelected ? 'bg-blue-600 border-blue-600 text-white' : 'border-slate-300'}
                `}>
                  {isSelected && <Check className="w-5 h-5" />}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Floating Action Button / Bar */}
      {selectedIds.size > 0 && (
         <div className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-slate-900 border-t dark:border-slate-700 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
           <div className="max-w-2xl mx-auto flex gap-4 items-center">
             <div className="flex-1 font-bold text-lg px-2">
               {selectedIds.size} selecionados
             </div>
             <Button size="lg" onClick={() => setIsConfirmOpen(true)} className="flex-1">
               Confirmar
             </Button>
           </div>
         </div>
      )}

      {/* Confirmation Modal */}
      <Modal
        isOpen={isConfirmOpen}
        onClose={() => setIsConfirmOpen(false)}
        title="Confirmar Ação"
        footer={
          <div className="flex gap-2 w-full">
            <Button variant="ghost" onClick={() => setIsConfirmOpen(false)} className="flex-1">Cancelar</Button>
            <Button onClick={handleConfirm} className="flex-1">Sim, Confirmar</Button>
          </div>
        }
      >
        <p className="text-lg text-center py-4">
          Deseja mover <strong>{selectedIds.size} itens</strong> para o status: <br/>
          <span className="font-bold text-blue-600">{config.action}</span>?
        </p>
      </Modal>
    </div>
  );
};

export default ProcessingScreen;

import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { Loader2, X } from 'lucide-react';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'outline';
  size?: 'sm' | 'md' | 'lg' | 'xl';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', size = 'md', isLoading, className, ...props 
}) => {
  const baseStyles = "font-medium rounded-lg transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center gap-2";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-md",
    secondary: "bg-blue-100 text-blue-900 hover:bg-blue-200", // Darkened text
    danger: "bg-red-600 text-white hover:bg-red-700 shadow-md",
    ghost: "bg-transparent text-slate-700 hover:bg-slate-100 dark:text-slate-200 dark:hover:bg-slate-800", // Darkened text
    outline: "border-2 border-blue-600 text-blue-700 hover:bg-blue-50 bg-transparent" // Darkened text
  };

  const sizes = {
    sm: "h-8 px-3 text-sm",
    md: "h-12 px-4 text-base",
    lg: "h-16 px-6 text-xl", // Large touch targets
    xl: "h-24 px-8 text-2xl font-bold", // Massive menu buttons
  };

  return (
    <button className={cn(baseStyles, variants[variant], sizes[size], className)} {...props}>
      {isLoading && <Loader2 className="w-5 h-5 animate-spin" />}
      {children}
    </button>
  );
};

// --- Card ---
export const Card: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ children, className, ...props }) => {
  return (
    <div className={cn("bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-300 dark:border-slate-600 p-4", className)} {...props}>
      {children}
    </div>
  );
};

// --- Modal ---
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  footer?: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, footer }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white dark:bg-slate-900 rounded-2xl w-full max-w-lg max-h-[90vh] flex flex-col shadow-xl border border-slate-200 dark:border-slate-700">
        <div className="flex justify-between items-center p-4 border-b border-slate-200 dark:border-slate-700">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
            <X className="w-6 h-6 text-slate-600" />
          </button>
        </div>
        <div className="p-4 overflow-y-auto flex-1">
          {children}
        </div>
        {footer && (
          <div className="p-4 border-t border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 rounded-b-2xl">
            {footer}
          </div>
        )}
      </div>
    </div>
  );
};

// --- Badge ---
export const Badge: React.FC<{ children: React.ReactNode, color?: 'blue' | 'green' | 'yellow' | 'red' }> = ({ children, color = 'blue' }) => {
  const colors = {
    blue: 'bg-blue-100 text-blue-900 border border-blue-200',
    green: 'bg-green-100 text-green-900 border border-green-200',
    yellow: 'bg-yellow-100 text-yellow-900 border border-yellow-200',
    red: 'bg-red-100 text-red-900 border border-red-200',
  };
  return (
    <span className={cn("px-2.5 py-0.5 rounded-full text-xs font-bold", colors[color])}>
      {children}
    </span>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { Sector, Employee } from '../types';
import { Button, Card } from '../components/UI';
import { Factory, Brush, Palette, ShieldCheck, User, ArrowLeft, KeyRound } from 'lucide-react';

const LoginScreen: React.FC = () => {
  const { setSector, loginUser, employees, currentSector, supervisorPassword } = useStore();

  const [selectedSector, setSelectedSector] = useState<Sector | null>(null);
  const [selectedUser, setSelectedUser] = useState<Employee | null>(null);
  const [inputPassword, setInputPassword] = useState('');
  const [error, setError] = useState('');

  const handleSectorSelect = (sector: Sector) => {
    setSelectedSector(sector);
    // Filter employees for this sector
  };

  const handleUserSelect = (user: Employee) => {
    if (selectedSector === Sector.SUPERVISOR) {
      setSelectedUser(user);
    } else {
      // Direct login for workers
      setSector(selectedSector);
      loginUser(user);
    }
  };

  const handleSupervisorLogin = () => {
    if (inputPassword === supervisorPassword) {
      if (selectedUser) {
        setSector(Sector.SUPERVISOR);
        loginUser(selectedUser);
      }
    } else {
      setError('Senha incorreta');
    }
  };

  const getSectorIcon = (s: Sector) => {
    switch(s) {
      case Sector.PRODUCTION: return <Factory className="w-12 h-12 mb-2" />;
      case Sector.FINISHING: return <Brush className="w-12 h-12 mb-2" />;
      case Sector.PAINTING: return <Palette className="w-12 h-12 mb-2" />;
      case Sector.SUPERVISOR: return <ShieldCheck className="w-12 h-12 mb-2" />;
    }
  };

  // Step 1: Sector Selection
  if (!selectedSector) {
    return (
      <div className="p-6 max-w-4xl mx-auto h-screen flex flex-col justify-center">
        <h1 className="text-3xl font-bold text-center mb-8 text-slate-900 dark:text-white">Selecione seu Setor</h1>
        <div className="grid grid-cols-2 gap-4">
          {Object.values(Sector).map((sector) => (
            <Button 
              key={sector} 
              variant={sector === Sector.SUPERVISOR ? 'secondary' : 'primary'} 
              size="xl" 
              onClick={() => handleSectorSelect(sector)}
              className="flex flex-col h-40 items-center justify-center text-center"
            >
              {getSectorIcon(sector)}
              {sector}
            </Button>
          ))}
        </div>
      </div>
    );
  }

  // Step 2 & 3: Profile & Auth
  const sectorEmployees = employees.filter(e => e.sector === selectedSector || (selectedSector === Sector.SUPERVISOR && e.sector === Sector.SUPERVISOR));

  return (
    <div className="p-6 max-w-lg mx-auto h-screen flex flex-col">
      <div className="mb-6 flex items-center">
        <Button variant="ghost" size="sm" onClick={() => { setSelectedSector(null); setSelectedUser(null); setError(''); }}>
          <ArrowLeft className="mr-2 h-4 w-4" /> Voltar
        </Button>
      </div>

      <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-6">
        Quem é você em {selectedSector}?
      </h2>

      {!selectedUser ? (
        <div className="grid grid-cols-1 gap-3 overflow-y-auto">
          {sectorEmployees.map(emp => (
            <Button 
              key={emp.id} 
              variant="outline" 
              size="lg" 
              className="justify-start text-lg"
              onClick={() => handleUserSelect(emp)}
            >
              <User className="mr-3 h-6 w-6" />
              {emp.name}
            </Button>
          ))}
          {sectorEmployees.length === 0 && (
            <p className="text-center text-slate-600">Nenhum funcionário encontrado.</p>
          )}
        </div>
      ) : (
        // Supervisor Password Check
        <Card className="flex flex-col gap-4 p-6">
          <div className="flex items-center gap-3 mb-2">
             <div className="bg-blue-100 p-3 rounded-full">
               <ShieldCheck className="w-8 h-8 text-blue-600" />
             </div>
             <div>
               <p className="text-sm text-slate-600">Login como</p>
               <h3 className="text-xl font-bold text-slate-900">{selectedUser.name}</h3>
             </div>
          </div>

          <div>
            <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Senha de Supervisor</label>
            <div className="relative">
              <KeyRound className="absolute left-3 top-3 h-5 w-5 text-slate-500" />
              <input 
                type="password"
                className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-lg text-slate-900"
                value={inputPassword}
                onChange={(e) => { setInputPassword(e.target.value); setError(''); }}
                placeholder="****"
              />
            </div>
            {error && <p className="text-red-600 text-sm mt-1">{error}</p>}
          </div>

          <Button size="lg" onClick={handleSupervisorLogin}>
            Entrar no Painel
          </Button>

          <Button variant="ghost" onClick={() => setSelectedUser(null)}>
            Trocar Usuário
          </Button>
        </Card>
      )}
    </div>
  );
};

export default LoginScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addProductionItems, currentUser, productionItems, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Stats for the day
  const today = new Date().toDateString();
  const todaysProduction = productionItems.filter(p => new Date(p.createdAt).toDateString() === today);
  const dailyTotal = todaysProduction.length;
  // Simplistic earnings calc for production (just showing volume for now as requested in prompt "Ganho diário" implies some value)
  const dailyValue = todaysProduction.reduce((acc, item) => {
    const model = vaseModels.find(v => v.id === item.modelId);
    return acc + (model?.costProduction || 0);
  }, 0);

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const confirmProduction = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const newItems: ProductionItem[] = [];
    const now = Date.now();

    draftItems.forEach(({ model, quantity }) => {
      for (let i = 0; i < quantity; i++) {
        newItems.push({
          id: uuidv4(),
          modelId: model.id,
          modelName: model.name,
          type: model.type,
          status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
          createdAt: now,
          updatedAt: now,
          producedBy: currentUser.id
        });
      }
    });

    addProductionItems(newItems);
    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback(`${newItems.length} itens lançados com sucesso!`);
    setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="p-4 pb-24 max-w-2xl mx-auto">
      {/* Navigation Header */}
      <div className="mb-4">
        <Button variant="ghost" size="sm" onClick={logout} className="pl-0 text-slate-700 dark:text-slate-300 hover:bg-transparent justify-start">
          <ArrowLeft className="mr-2 h-5 w-5" /> Voltar
        </Button>
      </div>

      {/* Header Banner */}
      <Card className="bg-gradient-to-r from-blue-700 to-blue-600 text-white mb-6 p-6 border-none shadow-md">
        <h2 className="text-lg text-blue-50 mb-1">Olá, {currentUser?.name}</h2>
        <div className="flex justify-between items-end">
          <div>
            <p className="text-3xl font-bold">{dailyTotal} vasos</p>
            <p className="text-sm text-blue-100">Produzidos hoje</p>
          </div>
          <div className="text-right">
             <p className="text-2xl font-bold">R$ {dailyValue.toFixed(2)}</p>
             <p className="text-sm text-blue-100">Custo produtivo dia</p>
          </div>
        </div>
      </Card>

      {/* Main Action */}
      <Button size="xl" onClick={() => setIsModalOpen(true)} className="w-full mb-6 shadow-lg border border-blue-700">
        <Plus className="w-8 h-8 mr-2" />
        Lançar Produção
      </Button>

      {/* Draft Area Preview */}
      {draftItems.length > 0 && (
        <div className="mb-6">
          <h3 className="text-lg font-bold mb-2 flex items-center text-slate-800 dark:text-slate-200">
             <ClipboardList className="mr-2" /> Rascunho Atual
          </h3>
          <div className="space-y-2">
            {draftItems.map((item) => (
               <Card key={item.model.id} className="flex justify-between items-center py-3 px-4 border-slate-300">
                 <span className="font-medium text-slate-900 dark:text-slate-100">{item.model.name}</span>
                 <Badge color="blue">{item.quantity} un</Badge>
               </Card>
            ))}
          </div>
        </div>
      )}

      {/* Feedback Snackbar */}
      {feedback && (
        <div className="fixed bottom-4 left-4 right-4 bg-green-700 text-white p-4 rounded-lg shadow-xl z-50 animate-in slide-in-from-bottom flex items-center">
           <Check className="mr-2" /> {feedback}
        </div>
      )}

      {/* Launch Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={selectedType ? `Lançar: ${selectedType}` : "Nova Produção"}
        footer={
          draftItems.length > 0 ? (
            <div className="flex gap-3 w-full">
              <div className="flex-1 text-slate-700 dark:text-slate-300 flex items-center justify-center font-bold">
                 Total: {draftItems.reduce((a,b) => a + b.quantity, 0)}
              </div>
              <Button onClick={confirmProduction} className="flex-1">
                Confirmar
              </Button>
            </div>
          ) : undefined
        }
      >
        {!selectedType ? (
          <div className="grid grid-cols-1 gap-4 mt-2">
