              {availableModels.map(model => {
                 const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
                 return (
                   <div key={model.id} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-lg">
                      <div className="flex-1">
