                      <div className="flex items-center gap-3">
                        {inDraft > 0 && (
                          <button onClick={() => removeFromDraft(model.id)} className="w-10 h-10 rounded-full bg-slate-200 text-slate-800 flex items-center justify-center active:bg-slate-300 border border-slate-300">
