                        <span className={`w-8 text-center font-bold text-xl ${inDraft > 0 ? 'text-blue-700' : 'text-slate-300'}`}>
                           {inDraft}
                        </span>
                        <button onClick={() => addToDraft(model)} className="w-10 h-10 rounded-full bg-blue-100 text-blue-900 flex items-center justify-center active:bg-blue-200 border border-blue-200">
                           <Plus className="w-6 h-6" />
                        </button>
                      </div>
                   </div>
                 );
              })}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

