    { icon: <Box />, label: 'Modelos' },
    { icon: <Users />, label: 'Func.' },
    { icon: <History />, label: 'Prod.' },
    { icon: <Settings />, label: 'Config' },
  ];

  return (
    <div className="h-screen flex flex-col bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white">
      <div className="p-4 bg-white dark:bg-slate-800 shadow-sm z-10 flex justify-between items-center border-b border-slate-200 dark:border-slate-700">
         <h1 className="text-xl font-bold">Painel Supervisor</h1>
         <Button variant="ghost" size="sm" onClick={logout}><LogOut className="w-5 h-5" /></Button>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        {activeTab === 0 && <DashboardTab />}
        {activeTab === 1 && <ModelsTab />}
        {activeTab === 2 && <EmployeesTab />}
        {activeTab === 3 && <div className="text-center p-4 font-medium text-slate-600">Histórico de Produção (Lista completa)</div>}
