      <div className="bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700 flex justify-around p-2 pb-6">
        {tabs.map((tab, idx) => (
          <button 
            key={idx}
            onClick={() => setActiveTab(idx)}
            className={`flex flex-col items-center p-2 rounded-lg transition-colors ${activeTab === idx ? 'text-blue-700 bg-blue-100 dark:text-blue-300 dark:bg-blue-900/40 font-bold' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
          >
            {React.cloneElement(tab.icon as React.ReactElement, { size: 24 })}
            <span className="text-xs mt-1">{tab.label}</span>
          </button>
        ))}
      </div>
    </div>
  );
};

