import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { Loader2, X } from 'lucide-react';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'outline' | 'fab';
  size?: 'sm' | 'md' | 'lg' | 'xl';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', size = 'md', isLoading, className, ...props 
}) => {
  // MD3: Buttons usually have fully rounded corners (pills) or slightly less rounded (rounded-xl)
  const baseStyles = "font-medium transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center gap-2 relative overflow-hidden";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-md hover:shadow-lg rounded-full",
    secondary: "bg-blue-100 text-blue-900 hover:bg-blue-200 rounded-full",
    danger: "bg-red-600 text-white hover:bg-red-700 shadow-md hover:shadow-lg rounded-full",
    ghost: "bg-transparent text-slate-700 hover:bg-slate-100 dark:text-slate-200 dark:hover:bg-slate-800 rounded-full",
    outline: "border border-slate-300 text-blue-700 hover:bg-blue-50 bg-transparent rounded-full",
    fab: "bg-blue-600 text-white shadow-lg hover:shadow-xl rounded-2xl" // Extended FAB style
  };

  const sizes = {
    sm: "h-8 px-4 text-sm",
    md: "h-10 px-6 text-sm",
    lg: "h-14 px-8 text-base", 
    xl: "h-16 px-8 text-lg font-bold",
  };

  return (
    <button className={cn(baseStyles, variants[variant], sizes[size], className)} {...props}>
      {isLoading && <Loader2 className="w-5 h-5 animate-spin" />}
      {children}
    </button>
  );
};

// --- Card ---
export const Card: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ children, className, ...props }) => {
  // MD3: Cards are Elevated, Filled, or Outlined. We use Elevated/Filled mix here.
  // rounded-2xl is standard for MD3 containers.
  return (
    <div className={cn("bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-5", className)} {...props}>
      {children}
    </div>
  );
};

// --- Modal ---
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  footer?: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, footer }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
      {/* MD3 Dialog: rounded-3xl, centered, high elevation */}
      <div className="bg-white dark:bg-slate-900 rounded-[28px] w-full max-w-sm md:max-w-md flex flex-col shadow-2xl animate-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 pt-6 pb-2">
          <h2 className="text-2xl font-normal text-slate-900 dark:text-white">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors">
            <X className="w-6 h-6 text-slate-600" />
          </button>
        </div>
        <div className="px-6 py-4 overflow-y-auto max-h-[60vh]">
          {children}
        </div>
        {footer && (
          <div className="px-6 pb-6 pt-2 flex justify-end gap-2">
            {footer}
          </div>
        )}
      </div>
    </div>
  );
};

// --- Badge ---
export const Badge: React.FC<{ children: React.ReactNode, color?: 'blue' | 'green' | 'yellow' | 'red' }> = ({ children, color = 'blue' }) => {
  // MD3 Badges are usually pills
  const colors = {
    blue: 'bg-blue-100 text-blue-900',
    green: 'bg-green-100 text-green-900',
    yellow: 'bg-yellow-100 text-yellow-900',
    red: 'bg-red-100 text-red-900',
  };
  return (
    <span className={cn("px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide", colors[color])}>
      {children}
    </span>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { Sector, Employee } from '../types';
import { Button, Card } from '../components/UI';
import { Factory, Brush, Palette, ShieldCheck, User, ArrowLeft, KeyRound } from 'lucide-react';

const LoginScreen: React.FC = () => {
  const { setSector, loginUser, employees, currentSector, supervisorPassword } = useStore();

  const [selectedSector, setSelectedSector] = useState<Sector | null>(null);
  const [selectedUser, setSelectedUser] = useState<Employee | null>(null);
  const [inputPassword, setInputPassword] = useState('');
  const [error, setError] = useState('');

  const handleSectorSelect = (sector: Sector) => {
    setSelectedSector(sector);
  };

  const handleUserSelect = (user: Employee) => {
    if (selectedSector === Sector.SUPERVISOR) {
      setSelectedUser(user);
    } else {
      setSector(selectedSector);
      loginUser(user);
    }
  };

  const handleSupervisorLogin = () => {
    if (inputPassword === supervisorPassword) {
      if (selectedUser) {
        setSector(Sector.SUPERVISOR);
        loginUser(selectedUser);
      }
    } else {
      setError('Senha incorreta');
    }
  };

  const getSectorIcon = (s: Sector) => {
    switch(s) {
      case Sector.PRODUCTION: return <Factory className="w-10 h-10 mb-3 text-blue-600" />;
      case Sector.FINISHING: return <Brush className="w-10 h-10 mb-3 text-purple-600" />;
      case Sector.PAINTING: return <Palette className="w-10 h-10 mb-3 text-orange-600" />;
      case Sector.SUPERVISOR: return <ShieldCheck className="w-10 h-10 mb-3 text-slate-600" />;
    }
  };

  // Step 1: Sector Selection
  if (!selectedSector) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl">
          <h1 className="text-4xl font-light text-center mb-10 text-slate-800">
            Bem-vindo ao <span className="font-bold text-blue-600">Home Pots</span>
          </h1>
          <p className="text-center text-slate-500 mb-8 -mt-6">Selecione seu setor para continuar</p>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {Object.values(Sector).map((sector) => (
              <button 
                key={sector} 
                onClick={() => handleSectorSelect(sector)}
                className="group bg-white hover:bg-blue-50 rounded-3xl p-6 shadow-sm hover:shadow-md transition-all duration-300 flex flex-col items-center justify-center h-48 border border-slate-100 active:scale-95"
              >
                <div className="bg-slate-50 group-hover:bg-white p-4 rounded-full transition-colors duration-300">
                  {getSectorIcon(sector)}
                </div>
                <span className="font-medium text-slate-700 group-hover:text-blue-900 text-lg mt-2">{sector}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Step 2 & 3: Profile & Auth
  const sectorEmployees = employees.filter(e => e.sector === selectedSector || (selectedSector === Sector.SUPERVISOR && e.sector === Sector.SUPERVISOR));

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="mb-6">
          <Button variant="ghost" size="sm" onClick={() => { setSelectedSector(null); setSelectedUser(null); setError(''); }}>
            <ArrowLeft className="mr-2 h-5 w-5" /> Voltar
          </Button>
        </div>

        <h2 className="text-3xl font-normal text-slate-800 mb-2">Identificação</h2>
        <p className="text-slate-500 mb-8">Quem é você em <span className="font-bold text-blue-600">{selectedSector}</span>?</p>

        {!selectedUser ? (
          <div className="space-y-3">
            {sectorEmployees.map(emp => (
              <div 
                key={emp.id}
                onClick={() => handleUserSelect(emp)}
                className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-center cursor-pointer hover:bg-slate-50 active:scale-[0.98] transition-all"
              >
                <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 mr-4">
                  <User className="h-6 w-6" />
                </div>
                <span className="text-lg font-medium text-slate-800">{emp.name}</span>
              </div>
            ))}
            {sectorEmployees.length === 0 && (
              <p className="text-center text-slate-500 py-10 bg-white rounded-2xl">Nenhum funcionário encontrado.</p>
            )}
          </div>
        ) : (
          <Card className="flex flex-col gap-6 p-8">
            <div className="flex flex-col items-center mb-2">
               <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 mb-4">
                 <ShieldCheck className="w-10 h-10" />
               </div>
               <h3 className="text-2xl font-bold text-slate-900">{selectedUser.name}</h3>
               <p className="text-slate-500">Acesso Supervisor</p>
            </div>

            <div>
              <div className="relative">
                <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />
                <input 
                  type="password"
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all text-lg text-slate-900"
                  value={inputPassword}
                  onChange={(e) => { setInputPassword(e.target.value); setError(''); }}
                  placeholder="Senha de acesso"
                />
              </div>
              {error && <p className="text-red-500 text-sm mt-2 ml-1">{error}</p>}
            </div>

            <Button size="lg" onClick={handleSupervisorLogin} className="w-full">
              Entrar no Painel
            </Button>

            <Button variant="ghost" onClick={() => setSelectedUser(null)} className="w-full">
              Trocar Usuário
            </Button>
          </Card>
        )}
      </div>
    </div>
  );
};

export default LoginScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, DollarSign } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addProductionItems, currentUser, productionItems, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Stats for the day
  const today = new Date().toDateString();
  const todaysProduction = productionItems.filter(p => new Date(p.createdAt).toDateString() === today);
  const dailyTotal = todaysProduction.length;

  const dailyValue = todaysProduction.reduce((acc, item) => {
    const model = vaseModels.find(v => v.id === item.modelId);
    return acc + (model?.costProduction || 0);
  }, 0);

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const confirmProduction = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const newItems: ProductionItem[] = [];
    const now = Date.now();

    draftItems.forEach(({ model, quantity }) => {
      for (let i = 0; i < quantity; i++) {
        newItems.push({
          id: uuidv4(),
          modelId: model.id,
          modelName: model.name,
          type: model.type,
          status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
          createdAt: now,
          updatedAt: now,
          producedBy: currentUser.id
        });
      }
    });

    addProductionItems(newItems);
    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback(`${newItems.length} itens lançados com sucesso!`);
    setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="pb-32 bg-slate-50 min-h-screen">
      {/* Top App Bar area */}
      <div className="bg-white p-4 sticky top-0 z-10 shadow-sm flex items-center justify-between">
         <Button variant="ghost" onClick={logout} className="text-slate-600">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <h1 className="text-xl font-medium text-slate-800">Produção</h1>
         <div className="w-10"></div> {/* Spacer for alignment */}
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">
        {/* Welcome & Stats */}
        <div className="bg-blue-600 rounded-3xl p-6 text-white shadow-lg shadow-blue-200">
          <div className="mb-6 opacity-90">Olá, {currentUser?.name}</div>
          <div className="grid grid-cols-2 gap-4">
             <div className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm">
                <div className="flex items-center gap-2 mb-1 text-blue-100">
                   <TrendingUp className="w-4 h-4" />
                   <span className="text-sm font-medium">Quantidade Hoje</span>
                </div>
                <div className="text-3xl font-bold">{dailyTotal}</div>
             </div>
             <div className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm">
                <div className="flex items-center gap-2 mb-1 text-blue-100">
                   <DollarSign className="w-4 h-4" />
                   <span className="text-sm font-medium">Custo Produção</span>
                </div>
                <div className="text-3xl font-bold">R$ {dailyValue.toFixed(0)}</div>
             </div>
          </div>
        </div>

        {/* Draft Area Preview */}
        {draftItems.length > 0 ? (
          <div className="animate-in slide-in-from-bottom-4 duration-500">
            <h3 className="text-lg font-normal text-slate-800 mb-3 px-2 flex items-center">
               <ClipboardList className="mr-2 text-blue-600" /> Rascunho
            </h3>
            <div className="space-y-2">
              {draftItems.map((item) => (
                 <div key={item.model.id} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center">
                   <span className="font-medium text-slate-700">{item.model.name}</span>
                   <Badge color="blue">{item.quantity} un</Badge>
                 </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-12 text-slate-400">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                <ClipboardList className="w-8 h-8" />
             </div>
             <p>Nenhum item no rascunho</p>
          </div>
        )}
      </div>

      {/* Floating Action Button (Extended) */}
      <div className="fixed bottom-6 right-6 z-20">
        <Button 
           variant="fab" 
           size="lg" // Custom large FAB size 
           onClick={() => setIsModalOpen(true)}
           className="h-16 pl-6 pr-8 rounded-[20px] shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all duration-300"
        >
          <Plus className="w-6 h-6 mr-2" />
          <span className="text-lg font-medium">Lançar Produção</span>
        </Button>
      </div>

      {/* Snackbar Feedback */}
      {feedback && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom fade-in duration-300">
           <div className="bg-slate-800 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3">
              <Check className="w-5 h-5 text-green-400" />
              <span className="font-medium">{feedback}</span>
           </div>
        </div>
      )}

      {/* Launch Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={selectedType ? `Lançar: ${selectedType}` : "Nova Produção"}
        footer={
          draftItems.length > 0 ? (
            <div className="flex items-center justify-between w-full">
               <div className="text-slate-600 font-medium ml-2">
                 Total: <span className="text-slate-900 font-bold text-lg">{draftItems.reduce((a,b) => a + b.quantity, 0)}</span>
               </div>
               <div className="flex gap-2">
                 <Button variant="ghost" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
                 <Button onClick={confirmProduction} variant="primary" className="px-6">
                   Confirmar
                 </Button>
               </div>
            </div>
          ) : undefined
        }
      >
        {!selectedType ? (
          <div className="grid grid-cols-1 gap-4 mt-2">
             <button onClick={() => setSelectedType(VaseType.WITH_SHELL)} className="group text-left p-4 rounded-2xl border border-slate-200 hover:border-blue-500 hover:bg-blue-50 transition-all">
                <div className="text-lg font-bold text-slate-800 group-hover:text-blue-700">Com Casca</div>
                <div className="text-sm text-slate-500">Acabamento Liso &rarr; Pintura</div>
             </button>
             <button onClick={() => setSelectedType(VaseType.WITHOUT_SHELL)} className="group text-left p-4 rounded-2xl border border-slate-200 hover:border-blue-500 hover:bg-blue-50 transition-all">
                <div className="text-lg font-bold text-slate-800 group-hover:text-blue-700">Sem Casca</div>
                <div className="text-sm text-slate-500">Acabamento Rústico &rarr; Estoque</div>
             </button>
          </div>
        ) : (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setSelectedType(null)} className="mb-2 pl-0 -ml-2 text-slate-500">
               <ArrowLeft className="mr-2 h-4 w-4" /> Voltar para Tipos
            </Button>

            <div className="grid gap-3 max-h-[50vh] overflow-y-auto pr-1">
              {availableModels.map(model => {
                 const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
                 return (
                   <div key={model.id} className="flex items-center justify-between p-3 bg-slate-50 border border-slate-200 rounded-xl">
                      <div className="flex-1">
                        <div className="font-medium text-slate-900">{model.name}</div>
                        <div className="text-xs text-slate-500">Custo: R$ {model.costProduction.toFixed(2)}</div>
                      </div>

                      <div className="flex items-center gap-3">
                        {inDraft > 0 && (
                          <button onClick={() => removeFromDraft(model.id)} className="w-8 h-8 rounded-full bg-slate-200 hover:bg-slate-300 text-slate-700 flex items-center justify-center transition-colors">
                             <Minus className="w-4 h-4" />
                          </button>
                        )}
                        <span className={`w-6 text-center font-bold ${inDraft > 0 ? 'text-blue-600' : 'text-slate-300'}`}>
                           {inDraft}
                        </span>
                        <button onClick={() => addToDraft(model)} className="w-8 h-8 rounded-full bg-blue-100 hover:bg-blue-200 text-blue-700 flex items-center justify-center transition-colors">
                           <Plus className="w-4 h-4" />
                        </button>
                      </div>
                   </div>
                 );
              })}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default ProductionScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { Sector, ItemStatus } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Check, Info, ArrowLeft, PaintBucket, Brush } from 'lucide-react';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, updateItemStatus, currentUser, logout } = useStore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);

  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    outputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Acabamento',
    icon: <Brush className="w-6 h-6 text-purple-600" />,
    action: 'Enviar para Pintura',
    emptyMsg: 'Tudo limpo por aqui!'
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    outputStatus: ItemStatus.FINISHED,
    title: 'Pintura',
    icon: <PaintBucket className="w-6 h-6 text-orange-600" />,
    action: 'Finalizar Vasos',
    emptyMsg: 'Nenhum vaso para pintura.'
  };

  const pendingItems = useMemo(() => 
    productionItems.filter(i => i.status === config.inputStatus)
    .sort((a,b) => b.createdAt - a.createdAt),
  [productionItems, config.inputStatus]);

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleConfirm = () => {
    if (!currentUser) return;
    updateItemStatus(Array.from(selectedIds), config.outputStatus, currentUser.id, stage);
    setSelectedIds(new Set());
    setIsConfirmOpen(false);
  };

  return (
    <div className="bg-slate-50 min-h-screen pb-32">
       {/* Top App Bar */}
       <div className="bg-white p-4 sticky top-0 z-10 shadow-sm flex items-center gap-4">
         <Button variant="ghost" onClick={logout} className="text-slate-600 -ml-2">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <div className="flex items-center gap-3">
            <div className="bg-slate-100 p-2 rounded-full">{config.icon}</div>
            <h1 className="text-xl font-medium text-slate-800">{config.title}</h1>
         </div>
      </div>

      <div className="p-4 max-w-3xl mx-auto">
        {pendingItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
             <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                <Check className="w-10 h-10 text-slate-300" />
             </div>
             <p className="font-medium text-lg">{config.emptyMsg}</p>
          </div>
        ) : (
          <div className="space-y-3">
            <p className="text-sm font-medium text-slate-500 ml-2 mb-2">{pendingItems.length} itens pendentes</p>
            {pendingItems.map((item) => {
              const isSelected = selectedIds.has(item.id);
              return (
                <div 
                  key={item.id}
                  onClick={() => toggleSelect(item.id)}
                  className={`
                    relative p-4 rounded-2xl border-2 transition-all cursor-pointer flex justify-between items-center group
                    ${isSelected 
                      ? 'border-blue-600 bg-blue-50 shadow-md' 
                      : 'border-transparent bg-white shadow-sm hover:shadow-md hover:border-slate-200'}
                  `}
                >
                  <div className="flex flex-col">
                     <span className={`font-medium text-lg ${isSelected ? 'text-blue-900' : 'text-slate-800'}`}>{item.modelName}</span>
                     <span className="text-xs text-slate-400 font-mono">ID: {item.id.slice(0, 8)}</span>
                  </div>

                  <div className={`
                     w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300
                     ${isSelected ? 'bg-blue-600 scale-110' : 'bg-slate-100 group-hover:bg-slate-200'}
                  `}>
                    {isSelected && <Check className="w-5 h-5 text-white" />}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Bottom Floating Action Bar */}
      {selectedIds.size > 0 && (
         <div className="fixed bottom-6 left-4 right-4 z-20 max-w-2xl mx-auto">
