import React, { useMemo } from 'react';
import { Modal, Badge } from './UI';
import { ProductionItem, VaseModel, PaymentRecord } from '../types';
import { Calendar, DollarSign, Box, Wallet } from 'lucide-react';

interface HistoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  mode: 'items' | 'financial' | 'payments'; // Added 'payments'
  items: ProductionItem[]; // Production items
  payments?: PaymentRecord[]; // Payment records
  vaseModels: VaseModel[];
  valueKey: 'productionValue' | 'finishingValue' | 'paintingValue';
  title: string;
}

const HistoryModal: React.FC<HistoryModalProps> = ({ 
  isOpen, onClose, mode, items, payments = [], vaseModels, valueKey, title 
}) => {

  // Sort items by date descending
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => b.updatedAt - a.updatedAt);
  }, [items]);

  // Sort payments by date descending
  const sortedPayments = useMemo(() => {
    return [...payments].sort((a, b) => b.date - a.date);
  }, [payments]);

  // Calculations
  const totalProduction = items.reduce((acc, curr) => acc + (curr[valueKey] || 0), 0);
  const totalPaid = payments.reduce((acc, curr) => acc + curr.amount, 0);

  // Group for financial view (Daily Production Summary)
  const financialData = useMemo(() => {
    const groups: Record<string, { date: string, count: number, total: number }> = {};

    sortedItems.forEach(item => {
      const date = new Date(item.updatedAt).toLocaleDateString('pt-BR');
      if (!groups[date]) {
        groups[date] = { date, count: 0, total: 0 };
      }
      groups[date].count += 1;
      groups[date].total += (item[valueKey] || 0);
    });

    return Object.values(groups).sort((a, b) => {
      const [d1, m1, y1] = a.date.split('/').map(Number);
      const [d2, m2, y2] = b.date.split('/').map(Number);
      return new Date(y2, m2 - 1, d2).getTime() - new Date(y1, m1 - 1, d1).getTime();
    });
  }, [sortedItems, valueKey]);

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={title}>
      <div className="space-y-4">
        {/* Header Summary */}
        <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex justify-between items-center">
          {mode === 'payments' ? (
             <>
                <div>
                  <p className="text-xs text-slate-500 uppercase font-bold">Total Recebido</p>
                  <p className="text-2xl font-bold text-green-600">R$ {totalPaid.toFixed(2)}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-slate-500 uppercase font-bold">Pagamentos</p>
                  <p className="text-xl font-medium text-slate-700">{payments.length}</p>
                </div>
             </>
          ) : (
            <>
              <div>
                 <p className="text-xs text-slate-500 uppercase font-bold">Total Produzido</p>
                 <p className="text-2xl font-bold text-slate-900">R$ {totalProduction.toFixed(2)}</p>
              </div>
              <div className="text-right">
                 <p className="text-xs text-slate-500 uppercase font-bold">Total Itens</p>
                 <p className="text-xl font-medium text-slate-700">{items.length}</p>
              </div>
            </>
          )}
        </div>

        <div className="relative">
          <div className="absolute inset-0 flex items-center" aria-hidden="true">
            <div className="w-full border-t border-slate-200" />
          </div>
          <div className="relative flex justify-center">
            <span className="bg-white px-2 text-xs text-slate-500 uppercase">
              {mode === 'items' && 'Detalhamento por Item'}
              {mode === 'financial' && 'Produção Diária'}
              {mode === 'payments' && 'Extrato de Pagamentos'}
            </span>
          </div>
        </div>

        {/* List Content */}
        <div className="space-y-2">

          {/* MODE: ITEMS */}
          {mode === 'items' && sortedItems.map(item => {
              const model = vaseModels.find(v => v.id === item.modelId) || { name: item.modelName };
              const date = new Date(item.updatedAt);
              return (
                <div key={item.id} className="flex justify-between items-center p-3 bg-white border border-slate-100 rounded-xl hover:bg-slate-50 transition-colors">
                  <div className="flex items-start gap-3">
                    <div className="bg-blue-50 p-2 rounded-full text-blue-600 mt-1">
                      <Box className="w-4 h-4" />
                    </div>
                    <div>
                      <p className="font-medium text-slate-900">{item.modelName}</p>
                      <p className="text-xs text-slate-400">
                        {date.toLocaleDateString('pt-BR')} • {date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute:'2-digit'})}
                      </p>
                      <Badge color={item.type === 'Com Casca' ? 'blue' : 'yellow'}>{item.type}</Badge>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-green-600">+ R$ {(item[valueKey] || 0).toFixed(2)}</p>
                  </div>
                </div>
              );
          })}

          {/* MODE: FINANCIAL (Daily Summary) */}
          {mode === 'financial' && financialData.map((day, idx) => (
              <div key={idx} className="flex justify-between items-center p-4 bg-white border border-slate-100 rounded-xl hover:bg-slate-50 transition-colors">
                 <div className="flex items-center gap-3">
                    <div className="bg-blue-50 p-2 rounded-full text-blue-600">
                      <Calendar className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="font-bold text-slate-900">{day.date}</p>
                      <p className="text-xs text-slate-500">{day.count} itens processados</p>
                    </div>
                 </div>
                 <div className="text-right">
                    <p className="text-lg font-bold text-blue-700">R$ {day.total.toFixed(2)}</p>
                 </div>
              </div>
          ))}

          {/* MODE: PAYMENTS */}
          {mode === 'payments' && sortedPayments.map((payment) => (
              <div key={payment.id} className="flex justify-between items-center p-4 bg-white border border-slate-100 rounded-xl hover:bg-slate-50 transition-colors">
                 <div className="flex items-center gap-3">
                    <div className="bg-green-50 p-2 rounded-full text-green-600">
                      <Wallet className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="font-bold text-slate-900">{new Date(payment.date).toLocaleDateString('pt-BR')}</p>
                      {payment.observation ? (
                        <p className="text-xs text-slate-500 italic max-w-[150px] truncate">"{payment.observation}"</p>
                      ) : (
                        <p className="text-xs text-slate-400">Pagamento recebido</p>
                      )}
                    </div>
                 </div>
                 <div className="text-right">
                    <p className="text-lg font-bold text-green-700">- R$ {payment.amount.toFixed(2)}</p>
                 </div>
              </div>
          ))}

          {/* Empty State */}
          {((mode === 'items' && items.length === 0) || 
            (mode === 'financial' && items.length === 0) || 
            (mode === 'payments' && payments.length === 0)) && (
             <div className="text-center py-10 text-slate-400">
               <p>Nenhum registro encontrado.</p>
             </div>
          )}
        </div>
      </div>
    </Modal>
  );
};

