import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, DollarSign, Wallet } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import HistoryModal from '../components/HistoryModal';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addProductionItems, currentUser, productionItems, payments, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  // 1. All items produced by THIS user (All Time)
  const myAllTimeProduction = useMemo(() => 
    productionItems.filter(p => p.producedBy === currentUser?.id),
  [productionItems, currentUser]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysProduction = myAllTimeProduction.filter(p => 
    new Date(p.createdAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysProduction.length;
  const dailyEarnings = myTodaysProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const confirmProduction = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const newItems: ProductionItem[] = [];
    const now = Date.now();

    draftItems.forEach(({ model, quantity }) => {
      for (let i = 0; i < quantity; i++) {
        newItems.push({
          id: uuidv4(),
          modelId: model.id,
          modelName: model.name,
          type: model.type,
          status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
          createdAt: now,
          updatedAt: now,
          producedBy: currentUser.id,
          productionValue: 0 // Placeholder, updated in store
        });
      }
    });

    addProductionItems(newItems);
    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback(`Produção registrada! + R$ ${draftItems.reduce((acc, item) => acc + (item.model.costProduction * item.quantity), 0).toFixed(2)}`);
    setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="pb-32 bg-slate-50 min-h-screen">
      {/* Top App Bar area */}
      <div className="bg-white p-4 sticky top-0 z-10 shadow-sm flex items-center justify-between">
         <Button variant="ghost" onClick={logout} className="text-slate-600">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <h1 className="text-xl font-medium text-slate-800">Setor de Produção</h1>
         <div className="w-10"></div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">
        {/* Financial Dashboard */}
        <div className="bg-blue-600 rounded-3xl p-6 text-white shadow-lg shadow-blue-200">
          <div className="flex justify-between items-start mb-6">
             <div>
               <p className="text-blue-100 font-medium">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Seu desempenho</h2>
             </div>
             <div className="bg-white/20 p-2 rounded-xl">
               <TrendingUp className="text-white" />
             </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* Card 1: Daily Production */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 text-blue-100">
                   <ClipboardList className="w-4 h-4" />
                   <span className="text-sm font-medium">Hoje</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs text-blue-200 mt-1 flex items-center">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Current Balance (Produced - Paid) */}
             <button 
                onClick={() => setHistoryMode('financial')} 
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 text-blue-100">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs text-blue-200 mt-1 flex items-center">
                  Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* Draft Area Preview */}
        {draftItems.length > 0 ? (
          <div className="animate-in slide-in-from-bottom-4 duration-500">
            <h3 className="text-lg font-normal text-slate-800 mb-3 px-2 flex items-center justify-between">
               <span className="flex items-center"><ClipboardList className="mr-2 text-blue-600" /> Rascunho</span>
               <span className="text-sm font-bold text-green-600 bg-green-50 px-3 py-1 rounded-full">
                 Est. + R$ {draftItems.reduce((acc, i) => acc + (i.model.costProduction * i.quantity), 0).toFixed(2)}
               </span>
            </h3>
            <div className="space-y-2">
              {draftItems.map((item) => (
                 <div key={item.model.id} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center">
                   <div>
                     <span className="font-medium text-slate-700 block">{item.model.name}</span>
                     <span className="text-xs text-slate-400">R$ {item.model.costProduction.toFixed(2)} / un</span>
                   </div>
                   <Badge color="blue">{item.quantity} un</Badge>
                 </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-12 text-slate-400">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                <ClipboardList className="w-8 h-8" />
             </div>
             <p>Nenhum item no rascunho</p>
          </div>
        )}
      </div>

      {/* Floating Action Button */}
      <div className="fixed bottom-6 right-6 z-20">
        <Button 
           variant="fab" 
           size="lg" 
           onClick={() => setIsModalOpen(true)}
           className="h-16 pl-6 pr-8 rounded-[20px] shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all duration-300"
        >
          <Plus className="w-6 h-6 mr-2" />
          <span className="text-lg font-medium">Registrar Produção</span>
        </Button>
      </div>

      {/* Snackbar Feedback */}
      {feedback && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom fade-in duration-300 w-full px-4 flex justify-center">
           <div className="bg-slate-800 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3">
              <Check className="w-5 h-5 text-green-400" />
              <span className="font-medium">{feedback}</span>
           </div>
        </div>
      )}

      {/* History Modal - Intermediate Selection for 'financial' click */}
      {historyMode === 'financial' ? (
        <Modal isOpen={true} onClose={() => setHistoryMode('none')} title="Detalhes Financeiros" footer={
          <Button variant="ghost" onClick={() => setHistoryMode('none')}>Fechar</Button>
        }>
           <div className="space-y-3 py-2">
             <button onClick={() => setHistoryMode('items')} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 flex justify-between items-center hover:bg-blue-50 hover:border-blue-200 transition-colors">
               <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-full text-blue-700"><ClipboardList className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold text-slate-800">Histórico de Produção</p>
                     <p className="text-xs text-slate-500">Veja tudo que você produziu</p>
                  </div>
               </div>
               <span className="font-bold text-blue-600">R$ {totalProducedValue.toFixed(2)}</span>
             </button>

             <button onClick={() => setHistoryMode('payments')} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 flex justify-between items-center hover:bg-green-50 hover:border-green-200 transition-colors">
               <div className="flex items-center gap-3">
                  <div className="bg-green-100 p-2 rounded-full text-green-700"><Wallet className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold text-slate-800">Pagamentos Recebidos</p>
                     <p className="text-xs text-slate-500">Extrato de valores pagos</p>
                  </div>
               </div>
               <span className="font-bold text-green-600">R$ {totalReceivedValue.toFixed(2)}</span>
             </button>

             <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between items-center">
               <span className="text-slate-500 font-medium">Saldo a Receber</span>
               <span className="text-xl font-bold text-slate-900">R$ {currentBalance.toFixed(2)}</span>
             </div>
           </div>
        </Modal>
      ) : (
        <HistoryModal 
          isOpen={historyMode !== 'none'}
          onClose={() => setHistoryMode('none')}
          mode={historyMode === 'items' ? 'items' : historyMode === 'payments' ? 'payments' : 'financial'}
          items={myAllTimeProduction}
          payments={myAllTimePayments}
          vaseModels={vaseModels}
          valueKey="productionValue"
          title={historyMode === 'items' ? 'Histórico de Produção' : historyMode === 'payments' ? 'Pagamentos Recebidos' : 'Extrato'}
        />
      )}

      {/* Launch Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={selectedType ? `Registrar: ${selectedType}` : "Nova Produção"}
        footer={
          draftItems.length > 0 ? (
            <div className="flex items-center justify-between w-full">
               <div className="text-slate-600 font-medium ml-2">
                 Total: <span className="text-slate-900 font-bold text-lg">{draftItems.reduce((a,b) => a + b.quantity, 0)}</span>
               </div>
               <div className="flex gap-2">
                 <Button variant="ghost" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
                 <Button onClick={confirmProduction} variant="primary" className="px-6">
                   Confirmar
                 </Button>
               </div>
            </div>
          ) : undefined
        }
      >
        {!selectedType ? (
          <div className="grid grid-cols-1 gap-4 mt-2">
             <button onClick={() => setSelectedType(VaseType.WITH_SHELL)} className="group text-left p-4 rounded-2xl border border-slate-200 hover:border-blue-500 hover:bg-blue-50 transition-all">
                <div className="text-lg font-bold text-slate-800 group-hover:text-blue-700">Com Casca</div>
                <div className="text-sm text-slate-500">Acabamento Liso &rarr; Pintura</div>
             </button>
             <button onClick={() => setSelectedType(VaseType.WITHOUT_SHELL)} className="group text-left p-4 rounded-2xl border border-slate-200 hover:border-blue-500 hover:bg-blue-50 transition-all">
                <div className="text-lg font-bold text-slate-800 group-hover:text-blue-700">Sem Casca</div>
                <div className="text-sm text-slate-500">Acabamento Rústico &rarr; Estoque</div>
             </button>
          </div>
        ) : (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setSelectedType(null)} className="mb-2 pl-0 -ml-2 text-slate-500">
               <ArrowLeft className="mr-2 h-4 w-4" /> Voltar para Tipos
            </Button>

            <div className="grid gap-3 max-h-[50vh] overflow-y-auto pr-1">
              {availableModels.map(model => {
                 const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
                 return (
                   <div key={model.id} className="flex items-center justify-between p-3 bg-slate-50 border border-slate-200 rounded-xl">
                      <div className="flex-1">
                        <div className="font-medium text-slate-900">{model.name}</div>
                        <div className="text-xs text-green-600 font-bold bg-green-50 inline-block px-2 py-0.5 rounded-md mt-1">
                          Ganho: R$ {model.costProduction.toFixed(2)}
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        {inDraft > 0 && (
                          <button onClick={() => removeFromDraft(model.id)} className="w-8 h-8 rounded-full bg-slate-200 hover:bg-slate-300 text-slate-700 flex items-center justify-center transition-colors">
                             <Minus className="w-4 h-4" />
                          </button>
                        )}
                        <span className={`w-6 text-center font-bold ${inDraft > 0 ? 'text-blue-600' : 'text-slate-300'}`}>
                           {inDraft}
                        </span>
                        <button onClick={() => addToDraft(model)} className="w-8 h-8 rounded-full bg-blue-100 hover:bg-blue-200 text-blue-700 flex items-center justify-center transition-colors">
                           <Plus className="w-4 h-4" />
                        </button>
                      </div>
                   </div>
                 );
              })}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default ProductionScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus } from '../types';
import { Button, Card, Modal } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, DollarSign, Hammer, Wallet, ClipboardList } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, processStageItems, currentUser, logout, vaseModels, payments } = useStore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  // 1. All items processed by THIS user (All Time)
  const myAllTimeItems = useMemo(() => productionItems.filter(p => {
    if (stage === 'finishing') return p.finishedBy === currentUser?.id;
    if (stage === 'painting') return p.paintedBy === currentUser?.id;
    return false;
  }), [productionItems, currentUser, stage]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysItems = myAllTimeItems.filter(p => 
     new Date(p.updatedAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysItems.length;
  const dailyEarnings = myTodaysItems.reduce((acc, item) => {
    if (stage === 'finishing') return acc + (item.finishingValue || 0);
    if (stage === 'painting') return acc + (item.paintingValue || 0);
    return acc;
  }, 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeItems.reduce((acc, item) => {
     if (stage === 'finishing') return acc + (item.finishingValue || 0);
     if (stage === 'painting') return acc + (item.paintingValue || 0);
     return acc;
  }, 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  // --- Config based on Stage ---
  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    title: 'Setor de Acabamento',
    icon: <Brush className="w-6 h-6 text-purple-600" />,
    actionLabel: 'Confirmar Acabamento',
    emptyMsg: 'Sem vasos para acabamento.',
    themeColor: 'purple'
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Setor de Pintura',
    icon: <PaintBucket className="w-6 h-6 text-orange-600" />,
    actionLabel: 'Confirmar Pintura',
    emptyMsg: 'Sem vasos para pintura.',
    themeColor: 'orange'
  };

  const pendingItems = useMemo(() => 
    productionItems.filter(i => i.status === config.inputStatus)
    .sort((a,b) => b.createdAt - a.createdAt),
  [productionItems, config.inputStatus]);

  // Calculate earnings for the SELECTED items (Pre-confirmation)
  const selectionEarnings = Array.from(selectedIds).reduce((acc, id) => {
    const item = pendingItems.find(i => i.id === id);
    if (!item) return acc;
    const model = vaseModels.find(v => v.id === item.modelId);
    if (!model) return acc;

    if (stage === 'finishing') return acc + (model.costFinishing || 0);
    if (stage === 'painting') return acc + ((model.priceSale || 0) * 0.10); // 10% commission
    return acc;
  }, 0);

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleConfirm = () => {
    if (!currentUser) return;
    processStageItems(Array.from(selectedIds), currentUser.id, stage);
    setSelectedIds(new Set());
    setIsConfirmOpen(false);
  };

  const getUnitValueDisplay = (modelId: string) => {
    const model = vaseModels.find(v => v.id === modelId);
    if (!model) return 'R$ 0.00';
    if (stage === 'finishing') return `R$ ${model.costFinishing?.toFixed(2)}`;
    if (stage === 'painting') return `R$ ${((model.priceSale || 0) * 0.10).toFixed(2)}`;
    return 'R$ 0.00';
  };

  const themeClasses = {
    purple: { bg: 'bg-purple-600', light: 'bg-purple-50', text: 'text-purple-600', border: 'border-purple-200' },
    orange: { bg: 'bg-orange-600', light: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-200' }
  }[config.themeColor];

  return (
    <div className="bg-slate-50 min-h-screen pb-32">
       {/* Top App Bar */}
       <div className="bg-white p-4 sticky top-0 z-10 shadow-sm flex items-center gap-4">
         <Button variant="ghost" onClick={logout} className="text-slate-600 -ml-2">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${themeClasses.light}`}>{config.icon}</div>
            <h1 className="text-xl font-medium text-slate-800">{config.title}</h1>
         </div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">

        {/* Financial Dashboard (Individual) */}
        <div className={`${themeClasses.bg} rounded-3xl p-6 text-white shadow-lg`}>
          <div className="flex justify-between items-start mb-6">
             <div>
               <p className="opacity-80 font-medium">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Produção do Dia</h2>
             </div>
             <div className="bg-white/20 p-2 rounded-xl">
               <TrendingUp className="text-white" />
             </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
             {/* Card 1: Daily Executed */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Hammer className="w-4 h-4" />
                   <span className="text-sm font-medium">Executados</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs opacity-70 mt-1 flex items-center">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Balance */}
             <button 
                onClick={() => setHistoryMode('financial')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs opacity-70 mt-1 flex items-center">
                   Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* Pending Items List */}
        {pendingItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
             <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                <Check className="w-10 h-10 text-slate-300" />
             </div>
             <p className="font-medium text-lg">{config.emptyMsg}</p>
          </div>
        ) : (
          <div className="space-y-3">
            <p className="text-sm font-medium text-slate-500 ml-2 mb-2 uppercase tracking-wide">Disponível para trabalho ({pendingItems.length})</p>
            {pendingItems.map((item) => {
              const isSelected = selectedIds.has(item.id);
              return (
                <div 
                  key={item.id}
                  onClick={() => toggleSelect(item.id)}
                  className={`
                    relative p-4 rounded-2xl border transition-all cursor-pointer flex justify-between items-center group
                    ${isSelected 
                      ? `border-${config.themeColor}-500 bg-${config.themeColor}-50 shadow-md` 
                      : 'border-slate-100 bg-white shadow-sm hover:shadow-md hover:border-slate-200'}
                  `}
                >
                  <div className="flex flex-col">
                     <span className={`font-medium text-lg ${isSelected ? `text-${config.themeColor}-900` : 'text-slate-800'}`}>{item.modelName}</span>
                     <span className="text-xs text-slate-400 font-mono mb-1">ID: {item.id.slice(0, 8)}</span>
                     <span className={`text-sm font-bold ${themeClasses.text}`}>
                        + {getUnitValueDisplay(item.modelId)}
                     </span>
                  </div>

                  <div className={`
                     w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300
                     ${isSelected ? `${themeClasses.bg} scale-110` : 'bg-slate-100 group-hover:bg-slate-200'}
                  `}>
                    {isSelected && <Check className="w-5 h-5 text-white" />}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Bottom Floating Action Bar */}
      {selectedIds.size > 0 && (
         <div className="fixed bottom-6 left-4 right-4 z-20 max-w-2xl mx-auto animate-in slide-in-from-bottom-4">
            <div className="bg-slate-900 text-white p-4 rounded-3xl shadow-2xl flex flex-col sm:flex-row items-center justify-between gap-4 pl-6 pr-4">
                <div className="flex flex-col">
                   <span className="text-slate-400 text-xs uppercase font-bold">Total a receber</span>
                   <div className="text-2xl font-bold text-green-400">
                     R$ {selectionEarnings.toFixed(2)}
                   </div>
                   <span className="text-xs text-slate-500">{selectedIds.size} itens selecionados</span>
                </div>
                <Button 
                   onClick={() => setIsConfirmOpen(true)} 
                   className={`${themeClasses.bg} text-white rounded-xl px-8 h-12 w-full sm:w-auto shadow-none hover:brightness-110`}
                >
                   {config.actionLabel}
                </Button>
            </div>
         </div>
      )}

      {/* Confirmation Modal */}
      <Modal
        isOpen={isConfirmOpen}
        onClose={() => setIsConfirmOpen(false)}
        title={config.actionLabel}
        footer={
          <div className="flex gap-2 w-full justify-end">
            <Button variant="ghost" onClick={() => setIsConfirmOpen(false)}>Cancelar</Button>
            <Button onClick={handleConfirm} className={themeClasses.bg}>Confirmar e Receber</Button>
          </div>
        }
      >
        <div className="py-4 space-y-4">
          <p className="text-slate-600 text-lg">
            Você confirma a execução do serviço em <strong>{selectedIds.size} vasos</strong>?
          </p> 

          <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
             <div className="flex justify-between items-center mb-1">
               <span className="text-slate-500">Serviço:</span>
               <span className="font-bold text-slate-800">{config.title}</span>
             </div>
             <div className="flex justify-between items-center">
               <span className="text-slate-500">Valor Total:</span>
               <span className="font-bold text-xl text-green-600">R$ {selectionEarnings.toFixed(2)}</span>
             </div>
          </div>

          <p className="text-xs text-slate-400 text-center">
            Ao confirmar, o valor será registrado na sua produção diária.
          </p>
        </div>
      </Modal>

      {/* History Modal - Intermediate Selection for 'financial' click */}
      {historyMode === 'financial' ? (
        <Modal isOpen={true} onClose={() => setHistoryMode('none')} title="Detalhes Financeiros" footer={
          <Button variant="ghost" onClick={() => setHistoryMode('none')}>Fechar</Button>
        }>
           <div className="space-y-3 py-2">
             <button onClick={() => setHistoryMode('items')} className={`w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 flex justify-between items-center hover:bg-blue-50 hover:border-blue-200 transition-colors`}>
               <div className="flex items-center gap-3">
                  <div className="bg-blue-100 p-2 rounded-full text-blue-700"><ClipboardList className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold text-slate-800">Histórico de Produção</p>
                     <p className="text-xs text-slate-500">Veja o que você executou</p>
                  </div>
               </div>
               <span className="font-bold text-blue-600">R$ {totalProducedValue.toFixed(2)}</span>
             </button>

             <button onClick={() => setHistoryMode('payments')} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 flex justify-between items-center hover:bg-green-50 hover:border-green-200 transition-colors">
               <div className="flex items-center gap-3">
                  <div className="bg-green-100 p-2 rounded-full text-green-700"><Wallet className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold text-slate-800">Pagamentos Recebidos</p>
                     <p className="text-xs text-slate-500">Extrato de valores pagos</p>
                  </div>
               </div>
               <span className="font-bold text-green-600">R$ {totalReceivedValue.toFixed(2)}</span>
             </button>

             <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between items-center">
               <span className="text-slate-500 font-medium">Saldo a Receber</span>
               <span className="text-xl font-bold text-slate-900">R$ {currentBalance.toFixed(2)}</span>
             </div>
           </div>
        </Modal>
      ) : (
        <HistoryModal 
          isOpen={historyMode !== 'none'}
          onClose={() => setHistoryMode('none')}
          mode={historyMode === 'items' ? 'items' : historyMode === 'payments' ? 'payments' : 'financial'}
          items={myAllTimeItems}
          payments={myAllTimePayments}
          vaseModels={vaseModels}
          valueKey={stage === 'finishing' ? 'finishingValue' : 'paintingValue'}
          title={historyMode === 'items' 
             ? `Histórico de Produção - ${config.title.replace('Setor de ', '')}`
             : historyMode === 'payments' 
                ? 'Pagamentos Recebidos' 
                : 'Extrato'}
        />
      )}
    </div>
  );
};

