                    onChange={e => setAmount(e.target.value)}
                    placeholder="0.00"
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Observação (Opcional)</label>
                <input 
                   className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                   value={obs}
                   onChange={e => setObs(e.target.value)}
                   placeholder="Ex: Adiantamento, Vale, Salário..."
                />
              </div>

              <Button onClick={handleRegisterPayment} className="w-full h-12 text-base shadow-lg" disabled={!selectedEmployee || !amount}>
                 Registrar Pagamento
              </Button>
              {feedback && <p className="text-success text-center font-bold text-sm">{feedback}</p>}
           </div>
        </Card>

        {/* History List */}
        <div>
           <h3 className="font-bold text-on-surface mb-3 px-1">Histórico Recente</h3>
           <div className="space-y-3">
              {payments.length === 0 ? (
                 <div className="text-center py-8 text-on-surface-variant bg-surface-variant/30 rounded-2xl border border-outline-variant/20">
                    Nenhum pagamento registrado.
                 </div>
              ) : (
                payments.sort((a,b) => b.date - a.date).map(p => (
                   <div key={p.id} className="bg-surface p-4 rounded-2xl border border-outline-variant/30 flex justify-between items-center shadow-sm">
                      <div>
                         <p className="font-bold text-on-surface">{p.employeeName}</p>
                         <div className="flex items-center gap-2 mt-1">
                            <span className="text-xs text-on-surface-variant">{new Date(p.date).toLocaleDateString()}</span>
                            <span className="w-1 h-1 bg-outline-variant rounded-full"></span>
                            <span className="text-xs text-on-surface-variant">{p.sector}</span>
                         </div>
                         {p.observation && <p className="text-xs text-on-surface-variant italic mt-1">"{p.observation}"</p>}
                      </div>
                      <span className="text-lg font-bold text-success bg-success-container/30 px-3 py-1 rounded-lg">
                         R$ {p.amount.toFixed(2)}
                      </span>
                   </div>
                ))
              )}
           </div>
        </div>
      </div>
    );
  };

  const ConfigTab = () => {
    const [confirmReset, setConfirmReset] = useState(false);
    return (
      <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <h2 className="text-2xl font-normal text-on-background px-1">Configurações</h2>
        <Card className="flex items-center justify-between p-5 cursor-pointer hover:bg-surface-variant/30 transition-colors" onClick={toggleTheme}>
           <div className="flex items-center gap-3">
             <div className="bg-surface-variant/50 p-2 rounded-full"><Moon className="w-5 h-5 text-on-surface-variant" /></div>
             <span className="font-medium text-on-surface">Modo Escuro</span>
           </div>
           <div className={`w-12 h-7 rounded-full p-1 transition-colors ${isDarkMode ? 'bg-primary' : 'bg-surface-variant'}`}>
              <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${isDarkMode ? 'translate-x-5' : 'translate-x-0'}`} />
           </div>
        </Card>

        <Card className="p-5 border-error/20 bg-error-container/20">
           <h3 className="font-bold text-error mb-2 flex items-center gap-2">
             <Trash className="w-4 h-4" /> Zona de Perigo
           </h3>
           {!confirmReset ? (
              <Button variant="danger" className="w-full bg-surface border border-error/30 text-error hover:bg-error-container shadow-none" onClick={() => setConfirmReset(true)}>Resetar Dados do Sistema</Button>
           ) : (
             <div className="flex gap-2">
               <Button variant="ghost" onClick={() => setConfirmReset(false)} className="flex-1">Cancelar</Button>
               <Button variant="danger" onClick={() => { resetData(); setConfirmReset(false); }} className="flex-1">Confirmar Reset</Button>
             </div>
           )}
        </Card>

        <Button variant="outline" className="w-full mt-4 text-on-surface-variant border-outline" onClick={logout}>
          <LogOut className="mr-2 h-4 w-4" /> Encerrar Sessão
        </Button>
      </div>
    );
  };

  // --- Main Layout ---

  const tabs = [
    { Icon: LayoutDashboard, label: 'Dash' },
    { Icon: Box, label: 'Modelos' },
    { Icon: Users, label: 'Func.' },
    { Icon: DollarSign, label: 'Pag.' },
    { Icon: Settings, label: 'Config' },
  ];

  return (
    <div className="h-screen flex flex-col bg-background">
      {/* Top Bar */}
      <div className="bg-surface p-4 shadow-sm z-10 flex justify-between items-center px-6 border-b border-outline-variant/10">
         <h1 className="text-xl font-medium text-on-surface">Painel Supervisor</h1>
         <div className="w-8 h-8 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container font-bold text-xs">SV</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 pb-24">
        {activeTab === 0 && <DashboardTab />}
        {activeTab === 1 && <ModelsTab />}
        {activeTab === 2 && <EmployeesTab />}
        {activeTab === 3 && <PaymentsTab />}
        {activeTab === 4 && <ConfigTab />}
      </div>

      {/* MD3 Bottom Navigation Bar */}
      <div className="bg-surface border-t border-outline-variant/20 flex justify-around p-2 pb-6 shadow-md z-20">
        {tabs.map((tab, idx) => {
          const isActive = activeTab === idx;
          return (
            <button 
              key={idx}
              onClick={() => setActiveTab(idx)}
              className="flex flex-col items-center justify-center w-full gap-1 group"
            >
              <div className={`px-5 py-1.5 rounded-full transition-all duration-300 ${isActive ? 'bg-primary-container' : 'bg-transparent group-hover:bg-surface-variant/50'}`}>
                <tab.Icon size={24} className={`transition-colors ${isActive ? 'text-on-primary-container' : 'text-on-surface-variant'}`} />
              </div>
              <span className={`text-[10px] font-medium transition-colors ${isActive ? 'text-on-surface' : 'text-on-surface-variant'}`}>
                {tab.label}
              </span>
            </button>
          )
        })}
      </div>
    </div>
  );
};

