export default SupervisorDashboard;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus } from '../types';
import { Button, Card, Modal } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, DollarSign, Hammer, Wallet, ClipboardList } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, processStageItems, currentUser, logout, vaseModels, payments } = useStore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  // 1. All items processed by THIS user (All Time)
  const myAllTimeItems = useMemo(() => productionItems.filter(p => {
    if (stage === 'finishing') return p.finishedBy === currentUser?.id;
    if (stage === 'painting') return p.paintedBy === currentUser?.id;
    return false;
  }), [productionItems, currentUser, stage]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysItems = myAllTimeItems.filter(p => 
     new Date(p.updatedAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysItems.length;
  const dailyEarnings = myTodaysItems.reduce((acc: number, item) => {
    if (stage === 'finishing') return acc + (item.finishingValue || 0);
    if (stage === 'painting') return acc + (item.paintingValue || 0);
    return acc;
  }, 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeItems.reduce((acc: number, item) => {
     if (stage === 'finishing') return acc + (item.finishingValue || 0);
     if (stage === 'painting') return acc + (item.paintingValue || 0);
     return acc;
  }, 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  // --- Config based on Stage ---
  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    title: 'Setor de Acabamento',
    icon: <Brush className="w-6 h-6 text-on-secondary-container" />,
    actionLabel: 'Confirmar Acabamento',
    emptyMsg: 'Sem vasos para acabamento.',
    themeColor: 'secondary'
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Setor de Pintura',
    icon: <PaintBucket className="w-6 h-6 text-on-primary-container" />,
    actionLabel: 'Confirmar Pintura',
    emptyMsg: 'Sem vasos para pintura.',
    themeColor: 'primary'
  };

  const pendingItems = useMemo(() => 
    productionItems.filter(i => i.status === config.inputStatus)
    .sort((a,b) => b.createdAt - a.createdAt),
  [productionItems, config.inputStatus]);

  // Calculate earnings for the SELECTED items (Pre-confirmation)
  const selectionEarnings = Array.from(selectedIds).reduce((acc: number, id) => {
    const item = pendingItems.find(i => i.id === id);
    if (!item) return acc;
    const model = vaseModels.find(v => v.id === item.modelId);
    if (!model) return acc;

    if (stage === 'finishing') return acc + (model.costFinishing || 0);
    if (stage === 'painting') return acc + ((model.priceSale || 0) * 0.10); // 10% commission
    return acc;
  }, 0);

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleConfirm = () => {
    if (!currentUser) return;
    processStageItems(Array.from(selectedIds), currentUser.id, stage);
    setSelectedIds(new Set());
    setIsConfirmOpen(false);
  };

  const getUnitValueDisplay = (modelId: string) => {
    const model = vaseModels.find(v => v.id === modelId);
    if (!model) return 'R$ 0.00';
    if (stage === 'finishing') return `R$ ${model.costFinishing?.toFixed(2)}`;
    if (stage === 'painting') return `R$ ${((model.priceSale || 0) * 0.10).toFixed(2)}`;
    return 'R$ 0.00';
  };

  // Maps logical theme color to actual tailwind classes constructed from variables
  const getThemeClasses = () => {
     if (config.themeColor === 'secondary') {
        return {
           bg: 'bg-secondary',
           container: 'bg-secondary-container',
           text: 'text-secondary',
           border: 'border-secondary',
           onContainer: 'text-on-secondary-container'
        };
     }
     return {
        bg: 'bg-primary',
        container: 'bg-primary-container',
        text: 'text-primary',
        border: 'border-primary',
        onContainer: 'text-on-primary-container'
     };
  };

  const themeClasses = getThemeClasses();

  return (
    <div className="bg-background min-h-screen pb-32">
       {/* Top App Bar */}
       <div className="bg-surface p-4 sticky top-0 z-10 shadow-sm flex items-center gap-4 border-b border-outline-variant/10">
         <Button variant="ghost" onClick={logout} className="text-on-surface-variant -ml-2">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${themeClasses.container}`}>{config.icon}</div>
            <h1 className="text-xl font-medium text-on-surface">{config.title}</h1>
         </div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">

        {/* Financial Dashboard (Individual) */}
        <div className={`${themeClasses.bg} rounded-3xl p-6 text-on-primary shadow-lg`}>
          <div className="flex justify-between items-start mb-6">
             <div>
               <p className="opacity-80 font-medium">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Produção do Dia</h2>
             </div>
             <div className="bg-white/20 p-2 rounded-xl">
               <TrendingUp className="text-white" />
             </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
             {/* Card 1: Daily Executed */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Hammer className="w-4 h-4" />
                   <span className="text-sm font-medium">Executados</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs opacity-70 mt-1 flex items-center">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Balance */}
             <button 
                onClick={() => setHistoryMode('financial')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs opacity-70 mt-1 flex items-center">
                   Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* Pending Items List */}
        {pendingItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-on-surface-variant">
             <div className="w-20 h-20 bg-surface-variant/30 rounded-full flex items-center justify-center mb-4">
                <Check className="w-10 h-10 text-on-surface-variant/50" />
             </div>
             <p className="font-medium text-lg">{config.emptyMsg}</p>
          </div>
        ) : (
          <div className="space-y-3">
            <p className="text-sm font-medium text-on-surface-variant ml-2 mb-2 uppercase tracking-wide">Disponível para trabalho ({pendingItems.length})</p>
            {pendingItems.map((item) => {
              const isSelected = selectedIds.has(item.id);
              return (
                <div 
                  key={item.id}
                  onClick={() => toggleSelect(item.id)}
                  className={`
                    relative p-4 rounded-2xl border transition-all cursor-pointer flex justify-between items-center group
                    ${isSelected 
                      ? `${themeClasses.container} border-transparent shadow-md` 
                      : 'border-outline-variant/30 bg-surface shadow-sm hover:shadow-md hover:border-outline-variant'}
                  `}
                >
                  <div className="flex flex-col">
                     <span className={`font-medium text-lg ${isSelected ? themeClasses.onContainer : 'text-on-surface'}`}>{item.modelName}</span>
                     <span className="text-xs text-on-surface-variant font-mono mb-1">ID: {item.id.slice(0, 8)}</span>
                     <span className={`text-sm font-bold ${isSelected ? themeClasses.onContainer : themeClasses.text}`}>
                        + {getUnitValueDisplay(item.modelId)}
                     </span>
                  </div>

                  <div className={`
                     w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300
                     ${isSelected ? `${themeClasses.bg} scale-110` : 'bg-surface-variant/50 group-hover:bg-surface-variant'}
                  `}>
                    {isSelected && <Check className="w-5 h-5 text-on-primary" />}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Bottom Floating Action Bar */}
      {selectedIds.size > 0 && (
         <div className="fixed bottom-6 left-4 right-4 z-20 max-w-2xl mx-auto animate-in slide-in-from-bottom-4">
            <div className="bg-on-surface text-surface p-4 rounded-3xl shadow-2xl flex flex-col sm:flex-row items-center justify-between gap-4 pl-6 pr-4">
                <div className="flex flex-col">
                   <span className="text-surface-variant text-xs uppercase font-bold">Total a receber</span>
                   <div className="text-2xl font-bold text-success">
                     R$ {selectionEarnings.toFixed(2)}
                   </div>
                   <span className="text-xs text-surface-variant">{selectedIds.size} itens selecionados</span>
                </div>
                <Button 
                   onClick={() => setIsConfirmOpen(true)} 
                   className={`${themeClasses.bg} text-on-primary rounded-xl px-8 h-12 w-full sm:w-auto shadow-none hover:brightness-110`}
                >
                   {config.actionLabel}
                </Button>
            </div>
         </div>
      )}

      {/* Confirmation Modal */}
      <Modal
        isOpen={isConfirmOpen}
        onClose={() => setIsConfirmOpen(false)}
        title={config.actionLabel}
        footer={
          <div className="flex gap-2 w-full justify-end">
            <Button variant="ghost" onClick={() => setIsConfirmOpen(false)}>Cancelar</Button>
            <Button onClick={handleConfirm} className={themeClasses.bg}>Confirmar e Receber</Button>
          </div>
        }
      >
        <div className="py-4 space-y-4">
          <p className="text-on-surface-variant text-lg">
            Você confirma a execução do serviço em <strong>{selectedIds.size} vasos</strong>?
          </p> 

          <div className="bg-surface-variant/30 p-4 rounded-2xl border border-outline-variant/30">
             <div className="flex justify-between items-center mb-1">
               <span className="text-on-surface-variant">Serviço:</span>
               <span className="font-bold text-on-surface">{config.title}</span>
             </div>
             <div className="flex justify-between items-center">
               <span className="text-on-surface-variant">Valor Total:</span>
