        </Modal>
      ) : (
        <HistoryModal 
          isOpen={historyMode !== 'none'}
          onClose={() => setHistoryMode('none')}
          mode={historyMode === 'items' ? 'items' : historyMode === 'payments' ? 'payments' : 'financial'}
