export default SupervisorDashboard;

export enum Sector {
  PRODUCTION = 'Produção',
  FINISHING = 'Acabamento',
  PAINTING = 'Pintura',
  SUPERVISOR = 'Supervisor',
}

export enum VaseType {
  WITH_SHELL = 'Com Casca',
  WITHOUT_SHELL = 'Sem Casca',
}

export enum ItemStatus {
  DRAFT = 'Rascunho', // Local UI state mostly, but good to have
  PRODUCED = 'Produzido',
  STOCK_NO_SHELL = 'Estoque (Sem Casca)',
  AWAITING_FINISHING = 'Aguardando Acabamento',
  AWAITING_PAINTING = 'Aguardando Pintura',
  FINISHED = 'Finalizado',
}

export interface VaseModel {
  id: string;
  name: string;
  type: VaseType;
  weightKg: number; // New field for raw material calculation
  costProduction: number; // Labor cost for molding
  costFinishing?: number; // Only With Shell
  priceSale?: number; // Only With Shell
  // Commission is calculated dynamically (10% of sale price)
}

export interface Employee {
  id: string;
  name: string;
  sector: Sector | 'General';
  active: boolean;
}

export interface PaymentRecord {
  id: string;
  employeeId: string;
  employeeName: string;
  sector: Sector | 'General';
  amount: number;
  date: number; // Timestamp
  observation?: string;
}

export interface ProductionItem {
  id: string;
  modelId: string;
  modelName: string; // Denormalized for easier display if model is deleted
  type: VaseType;
  status: ItemStatus;
  createdAt: number; // Timestamp
  updatedAt: number; // Timestamp

  // Worker Tracking
  producedBy: string; // Employee ID
  finishedBy?: string; // Employee ID
  paintedBy?: string; // Employee ID

  // Value Tracking (Frozen at moment of execution)
  productionValue: number; // How much the producer earned (Labor)
  rawMaterialCost: number; // Cost of raw material (weight * rate) at time of production
  finishingValue?: number; // How much the finisher earned
  paintingValue?: number;  // How much the painter earned
}

export interface AppState {
  isDarkMode: boolean;
  supervisorPassword: string; // In real app, hash this.
  currentUser: Employee | null;
  currentSector: Sector | null;

  // Configs
  rawMaterialCostPerKg: number; // Default 0.26

  employees: Employee[];
  vaseModels: VaseModel[];
  productionItems: ProductionItem[];
  payments: PaymentRecord[];

  // Actions
  toggleTheme: () => void;
  setSector: (sector: Sector | null) => void;
  loginUser: (user: Employee) => void;
  logout: () => void;

  addProductionItems: (items: ProductionItem[]) => void;
  // Updated signature to handle logic internally based on stage
  processStageItems: (itemIds: string[], workerId: string, stage: 'finishing' | 'painting', timestamp: number) => void;

  // Supervisor Actions
  updateSupervisorPassword: (pass: string) => void;
  updateRawMaterialCostPerKg: (value: number) => void;
  addVaseModel: (model: VaseModel) => void;
  updateVaseModel: (model: VaseModel) => void;
  deleteVaseModel: (id: string) => void;
  addEmployee: (emp: Employee) => void;
  updateEmployee: (emp: Employee) => void;
  addPayment: (payment: PaymentRecord) => void;
  resetData: () => void;
}

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { AppState, ItemStatus, Sector, VaseType } from './types';
import { INITIAL_EMPLOYEES, INITIAL_VASES, DEFAULT_SUPERVISOR_PASS } from './constants';

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      rawMaterialCostPerKg: 0.26, // Default per requirement

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => set({ currentUser: user }),

      logout: () => set({ currentUser: null, currentSector: null }),

      addProductionItems: (items) => set((state) => {
        // Hydrate items with current production costs from models
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            // Calculate Raw Material Cost Snapshot: Weight * Current Rate
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });
        return { productionItems: [...state.productionItems, ...hydratedItems] };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        // Use the passed timestamp instead of Date.now()
        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            if (stage === 'finishing') {
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: model?.costFinishing || 0
              };
            }

            if (stage === 'painting') {
               // Calculate 10% commission
               const salePrice = model?.priceSale || 0;
               const commission = salePrice * 0.10;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });
        return { productionItems: updatedItems };
      }),

      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set({ rawMaterialCostPerKg: value }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),

      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),

      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),

      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),

      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),

      addPayment: (payment) => set((state) => ({ payments: [payment, ...state.payments] })),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26
      }),
    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, DollarSign, Wallet, Calendar } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import HistoryModal from '../components/HistoryModal';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addProductionItems, currentUser, productionItems, payments, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Date State - Default to Today "YYYY-MM-DD"
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  // 1. All items produced by THIS user (All Time)
  const myAllTimeProduction = useMemo(() => 
    productionItems.filter(p => p.producedBy === currentUser?.id),
  [productionItems, currentUser]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysProduction = myAllTimeProduction.filter(p => 
    new Date(p.createdAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysProduction.length;
  const dailyEarnings = myTodaysProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const confirmProduction = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const newItems: ProductionItem[] = [];

    // Create timestamp from selected date (set to noon to avoid timezone rolling back the day)
    const productionDate = new Date(selectedDate + 'T12:00:00').getTime();

    draftItems.forEach(({ model, quantity }) => {
      for (let i = 0; i < quantity; i++) {
        newItems.push({
          id: uuidv4(),
          modelId: model.id,
          modelName: model.name,
          type: model.type,
          status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
          createdAt: productionDate, // Use the selected date
          updatedAt: productionDate, // Use the selected date
          producedBy: currentUser.id,
          productionValue: 0, // Placeholder, updated in store
          rawMaterialCost: 0 // Placeholder, updated in store
        });
      }
    });

    addProductionItems(newItems);
    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback(`Produção registrada! + R$ ${draftItems.reduce((acc, item) => acc + (item.model.costProduction * item.quantity), 0).toFixed(2)}`);
    setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="pb-32 bg-background min-h-screen">
      {/* Top App Bar area */}
      <div className="bg-surface p-4 sticky top-0 z-10 shadow-sm flex items-center justify-between border-b border-outline-variant/10">
         <Button variant="ghost" onClick={logout} className="text-on-surface-variant">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <h1 className="text-xl font-medium text-on-surface">Setor de Produção</h1>
         <div className="w-10"></div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">
        {/* Financial Dashboard */}
        <div className="bg-primary rounded-3xl p-6 text-on-primary shadow-lg shadow-primary/30">
          <div className="flex justify-between items-start mb-6">
             <div>
               <p className="text-on-primary/80 font-medium">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Seu desempenho</h2>
             </div>
             <div className="bg-on-primary/10 p-2 rounded-xl">
               <TrendingUp className="text-on-primary" />
             </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* Card 1: Daily Production */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-on-primary/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-on-primary/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-on-primary/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 text-on-primary/80">
                   <ClipboardList className="w-4 h-4" />
                   <span className="text-sm font-medium">Hoje</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs text-on-primary/70 mt-1 flex items-center">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Current Balance (Produced - Paid) */}
             <button 
                onClick={() => setHistoryMode('financial')} 
                className="bg-on-primary/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-on-primary/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-on-primary/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 text-on-primary/80">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs text-on-primary/70 mt-1 flex items-center">
                  Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* Draft Area Preview */}
        {draftItems.length > 0 ? (
          <div className="animate-in slide-in-from-bottom-4 duration-500">
            <h3 className="text-lg font-normal text-on-background mb-3 px-2 flex items-center justify-between">
               <span className="flex items-center"><ClipboardList className="mr-2 text-primary" /> Rascunho</span>
               <span className="text-sm font-bold text-on-success-container bg-success-container px-3 py-1 rounded-full">
                 Est. + R$ {draftItems.reduce((acc, i) => acc + (i.model.costProduction * i.quantity), 0).toFixed(2)}
               </span>
            </h3>
            <div className="space-y-2">
              {draftItems.map((item) => (
                 <div key={item.model.id} className="bg-surface p-4 rounded-2xl shadow-sm border border-outline-variant/30 flex justify-between items-center">
                   <div>
                     <span className="font-medium text-on-surface block">{item.model.name}</span>
                     <span className="text-xs text-on-surface-variant">R$ {item.model.costProduction.toFixed(2)} / un</span>
                   </div>
                   <Badge color="blue">{item.quantity} un</Badge>
                 </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-12 text-on-surface-variant">
             <div className="w-16 h-16 bg-surface-variant/30 rounded-full flex items-center justify-center mb-4">
                <ClipboardList className="w-8 h-8 opacity-50" />
             </div>
             <p>Nenhum item no rascunho</p>
          </div>
        )}
      </div>

      {/* Floating Action Button */}
      <div className="fixed bottom-6 right-6 z-20">
        <Button 
           variant="fab" 
           size="lg" 
           onClick={() => setIsModalOpen(true)}
           className="h-16 pl-6 pr-8 rounded-[20px]"
        >
          <Plus className="w-6 h-6 mr-2" />
          <span className="text-lg font-medium">Registrar Produção</span>
        </Button>
      </div>

      {/* Snackbar Feedback */}
      {feedback && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom fade-in duration-300 w-full px-4 flex justify-center">
           <div className="bg-on-surface text-surface px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3">
              <Check className="w-5 h-5 text-success" />
              <span className="font-medium">{feedback}</span>
           </div>
        </div>
      )}

      {/* History Modal - Intermediate Selection for 'financial' click */}
      {historyMode === 'financial' ? (
        <Modal isOpen={true} onClose={() => setHistoryMode('none')} title="Detalhes Financeiros" footer={
          <Button variant="ghost" onClick={() => setHistoryMode('none')}>Fechar</Button>
        }>
           <div className="space-y-3 py-2">
             <button onClick={() => setHistoryMode('items')} className="w-full p-4 rounded-2xl bg-surface-variant/20 border border-outline-variant/20 flex justify-between items-center hover:bg-primary-container/20 hover:border-primary/20 transition-colors">
               <div className="flex items-center gap-3">
                  <div className="bg-primary-container p-2 rounded-full text-on-primary-container"><ClipboardList className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold text-on-surface">Histórico de Produção</p>
                     <p className="text-xs text-on-surface-variant">Veja tudo que você produziu</p>
                  </div>
               </div>
               <span className="font-bold text-primary">R$ {totalProducedValue.toFixed(2)}</span>
             </button>

             <button onClick={() => setHistoryMode('payments')} className="w-full p-4 rounded-2xl bg-surface-variant/20 border border-outline-variant/20 flex justify-between items-center hover:bg-success-container/20 hover:border-success/20 transition-colors">
               <div className="flex items-center gap-3">
                  <div className="bg-success-container p-2 rounded-full text-on-success-container"><Wallet className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold text-on-surface">Pagamentos Recebidos</p>
                     <p className="text-xs text-on-surface-variant">Extrato de valores pagos</p>
                  </div>
               </div>
               <span className="font-bold text-success">R$ {totalReceivedValue.toFixed(2)}</span>
             </button>

             <div className="mt-4 pt-4 border-t border-outline-variant/20 flex justify-between items-center">
               <span className="text-on-surface-variant font-medium">Saldo a Receber</span>
               <span className="text-xl font-bold text-on-surface">R$ {currentBalance.toFixed(2)}</span>
             </div>
           </div>
        </Modal>
      ) : (
        <HistoryModal 
          isOpen={historyMode !== 'none'}
          onClose={() => setHistoryMode('none')}
          mode={historyMode === 'items' ? 'items' : historyMode === 'payments' ? 'payments' : 'financial'}
          items={myAllTimeProduction}
          payments={myAllTimePayments}
          vaseModels={vaseModels}
          valueKey="productionValue"
          title={historyMode === 'items' ? 'Histórico de Produção' : historyMode === 'payments' ? 'Pagamentos Recebidos' : 'Extrato'}
        />
      )}

      {/* Launch Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={selectedType ? `Registrar: ${selectedType}` : "Nova Produção"}
        footer={
          draftItems.length > 0 ? (
            <div className="flex flex-col gap-4 w-full">
               <div className="bg-surface-variant/30 p-3 rounded-xl border border-outline-variant/30">
                 <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block flex items-center gap-2">
                   <Calendar className="w-3 h-3" /> Data de Produção
                 </label>
                 <input 
                   type="date" 
                   className="w-full p-2 bg-surface border border-outline-variant rounded-lg text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                   value={selectedDate}
                   onChange={(e) => setSelectedDate(e.target.value)}
                   required
                 />
               </div>

               <div className="flex items-center justify-between w-full">
                  <div className="text-on-surface-variant font-medium ml-2">
                    Total: <span className="text-on-surface font-bold text-lg">{draftItems.reduce((a,b) => a + b.quantity, 0)}</span>
                  </div>
                  <div className="flex gap-2">
                    <Button variant="ghost" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
                    <Button onClick={confirmProduction} variant="primary" className="px-6">
                      Confirmar
                    </Button>
                  </div>
               </div>
            </div>
          ) : undefined
        }
      >
        {!selectedType ? (
          <div className="grid grid-cols-1 gap-4 mt-2">
             <button onClick={() => setSelectedType(VaseType.WITH_SHELL)} className="group text-left p-4 rounded-2xl border border-outline-variant/30 hover:border-primary hover:bg-primary-container/20 transition-all">
                <div className="text-lg font-bold text-on-surface group-hover:text-primary">Com Casca</div>
                <div className="text-sm text-on-surface-variant">Acabamento Liso &rarr; Pintura</div>
             </button>
             <button onClick={() => setSelectedType(VaseType.WITHOUT_SHELL)} className="group text-left p-4 rounded-2xl border border-outline-variant/30 hover:border-primary hover:bg-primary-container/20 transition-all">
                <div className="text-lg font-bold text-on-surface group-hover:text-primary">Sem Casca</div>
                <div className="text-sm text-on-surface-variant">Acabamento Rústico &rarr; Estoque</div>
             </button>
          </div>
        ) : (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setSelectedType(null)} className="mb-2 pl-0 -ml-2 text-on-surface-variant">
               <ArrowLeft className="mr-2 h-4 w-4" /> Voltar para Tipos
            </Button>

            <div className="grid gap-3 max-h-[50vh] overflow-y-auto pr-1">
              {availableModels.map(model => {
                 const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
                 return (
                   <div key={model.id} className="flex items-center justify-between p-3 bg-surface border border-outline-variant/30 rounded-xl">
                      <div className="flex-1">
                        <div className="font-medium text-on-surface">{model.name}</div>
                        <div className="text-xs text-on-success-container font-bold bg-success-container inline-block px-2 py-0.5 rounded-md mt-1">
                          Ganho: R$ {model.costProduction.toFixed(2)}
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        {inDraft > 0 && (
                          <button onClick={() => removeFromDraft(model.id)} className="w-8 h-8 rounded-full bg-surface-variant hover:bg-surface-variant/80 text-on-surface-variant flex items-center justify-center transition-colors">
                             <Minus className="w-4 h-4" />
                          </button>
                        )}
                        <span className={`w-6 text-center font-bold ${inDraft > 0 ? 'text-primary' : 'text-on-surface-variant'}`}>
                           {inDraft}
                        </span>
                        <button onClick={() => addToDraft(model)} className="w-8 h-8 rounded-full bg-primary-container hover:bg-primary-container/80 text-on-primary-container flex items-center justify-center transition-colors">
                           <Plus className="w-4 h-4" />
                        </button>
                      </div>
                   </div>
                 );
              })}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default ProductionScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus } from '../types';
import { Button, Card, Modal } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, DollarSign, Hammer, Wallet, ClipboardList, Calendar } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, processStageItems, currentUser, logout, vaseModels, payments } = useStore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);

  // Date State for Processing Date - Default Today
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  // 1. All items processed by THIS user (All Time)
  const myAllTimeItems = useMemo(() => productionItems.filter(p => {
    if (stage === 'finishing') return p.finishedBy === currentUser?.id;
    if (stage === 'painting') return p.paintedBy === currentUser?.id;
    return false;
  }), [productionItems, currentUser, stage]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysItems = myAllTimeItems.filter(p => 
     new Date(p.updatedAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysItems.length;
  const dailyEarnings = myTodaysItems.reduce<number>((acc, item) => {
    if (stage === 'finishing') return acc + (item.finishingValue || 0);
    if (stage === 'painting') return acc + (item.paintingValue || 0);
    return acc;
  }, 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeItems.reduce<number>((acc, item) => {
     if (stage === 'finishing') return acc + (item.finishingValue || 0);
     if (stage === 'painting') return acc + (item.paintingValue || 0);
     return acc;
  }, 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  // --- Config based on Stage ---
  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    title: 'Setor de Acabamento',
    icon: <Brush className="w-6 h-6 text-on-secondary-container" />,
    actionLabel: 'Confirmar Acabamento',
    emptyMsg: 'Sem vasos para acabamento.',
    themeColor: 'secondary'
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Setor de Pintura',
    icon: <PaintBucket className="w-6 h-6 text-on-primary-container" />,
    actionLabel: 'Confirmar Pintura',
    emptyMsg: 'Sem vasos para pintura.',
    themeColor: 'primary'
  };

  const pendingItems = useMemo(() => 
    productionItems.filter(i => i.status === config.inputStatus)
    .sort((a,b) => b.createdAt - a.createdAt),
  [productionItems, config.inputStatus]);

  // Calculate earnings for the SELECTED items (Pre-confirmation)
  const selectionEarnings = Array.from(selectedIds).reduce<number>((acc, id) => {
    const item = pendingItems.find(i => i.id === id);
    if (!item) return acc;
    const model = vaseModels.find(v => v.id === item.modelId);
    if (!model) return acc;

    if (stage === 'finishing') return acc + (model.costFinishing || 0);
    if (stage === 'painting') return acc + ((model.priceSale || 0) * 0.10); // 10% commission
    return acc;
  }, 0);

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleConfirm = () => {
    if (!currentUser) return;

    // Create timestamp from selected date
    const processDate = new Date(selectedDate + 'T12:00:00').getTime();

    processStageItems(Array.from(selectedIds), currentUser.id, stage, processDate);
    setSelectedIds(new Set());
    setIsConfirmOpen(false);
  };

  const getUnitValueDisplay = (modelId: string) => {
    const model = vaseModels.find(v => v.id === modelId);
    if (!model) return 'R$ 0.00';
    if (stage === 'finishing') return `R$ ${model.costFinishing?.toFixed(2)}`;
    if (stage === 'painting') return `R$ ${((model.priceSale || 0) * 0.10).toFixed(2)}`;
    return 'R$ 0.00';
  };

  // Maps logical theme color to actual tailwind classes constructed from variables
  const getThemeClasses = () => {
     if (config.themeColor === 'secondary') {
        return {
           bg: 'bg-secondary',
           container: 'bg-secondary-container',
           text: 'text-secondary',
           border: 'border-secondary',
           onContainer: 'text-on-secondary-container'
        };
     }
     return {
        bg: 'bg-primary',
        container: 'bg-primary-container',
        text: 'text-primary',
        border: 'border-primary',
        onContainer: 'text-on-primary-container'
     };
  };

  const themeClasses = getThemeClasses();

  return (
    <div className="bg-background min-h-screen pb-32">
       {/* Top App Bar */}
       <div className="bg-surface p-4 sticky top-0 z-10 shadow-sm flex items-center gap-4 border-b border-outline-variant/10">
         <Button variant="ghost" onClick={logout} className="text-on-surface-variant -ml-2">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${themeClasses.container}`}>{config.icon}</div>
            <h1 className="text-xl font-medium text-on-surface">{config.title}</h1>
         </div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">

        {/* Financial Dashboard (Individual) */}
        <div className={`${themeClasses.bg} rounded-3xl p-6 text-on-primary shadow-lg`}>
          <div className="flex justify-between items-start mb-6">
             <div>
               <p className="opacity-80 font-medium">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Produção do Dia</h2>
             </div>
             <div className="bg-white/20 p-2 rounded-xl">
               <TrendingUp className="text-white" />
             </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
             {/* Card 1: Daily Executed */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Hammer className="w-4 h-4" />
                   <span className="text-sm font-medium">Executados</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs opacity-70 mt-1 flex items-center">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Balance */}
             <button 
                onClick={() => setHistoryMode('financial')}
                className="bg-white/10 rounded-2xl p-4 backdrop-blur-sm hover:bg-white/20 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-white/50 outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs opacity-70 mt-1 flex items-center">
                   Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* Pending Items List */}
        {pendingItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-on-surface-variant">
             <div className="w-20 h-20 bg-surface-variant/30 rounded-full flex items-center justify-center mb-4">
                <Check className="w-10 h-10 text-on-surface-variant/50" />
             </div>
             <p className="font-medium text-lg">{config.emptyMsg}</p>
          </div>
        ) : (
          <div className="space-y-3">
            <p className="text-sm font-medium text-on-surface-variant ml-2 mb-2 uppercase tracking-wide">Disponível para trabalho ({pendingItems.length})</p>
            {pendingItems.map((item) => {
              const isSelected = selectedIds.has(item.id);
              return (
                <div 
                  key={item.id}
                  onClick={() => toggleSelect(item.id)}
                  className={`
                    relative p-4 rounded-2xl border transition-all cursor-pointer flex justify-between items-center group
                    ${isSelected 
                      ? `${themeClasses.container} border-transparent shadow-md` 
                      : 'border-outline-variant/30 bg-surface shadow-sm hover:shadow-md hover:border-outline-variant'}
                  `}
                >
                  <div className="flex flex-col">
                     <span className={`font-medium text-lg ${isSelected ? themeClasses.onContainer : 'text-on-surface'}`}>{item.modelName}</span>
                     <span className="text-xs text-on-surface-variant font-mono mb-1">ID: {item.id.slice(0, 8)}</span>
                     <span className={`text-sm font-bold ${isSelected ? themeClasses.onContainer : themeClasses.text}`}>
                        + {getUnitValueDisplay(item.modelId)}
                     </span>
                  </div>

                  <div className={`
                     w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300
                     ${isSelected ? `${themeClasses.bg} scale-110` : 'bg-surface-variant/50 group-hover:bg-surface-variant'}
                  `}>
                    {isSelected && <Check className="w-5 h-5 text-on-primary" />}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Bottom Floating Action Bar */}
      {selectedIds.size > 0 && (
         <div className="fixed bottom-6 left-4 right-4 z-20 max-w-2xl mx-auto animate-in slide-in-from-bottom-4">
            <div className="bg-on-surface text-surface p-4 rounded-3xl shadow-2xl flex flex-col sm:flex-row items-center justify-between gap-4 pl-6 pr-4">
                <div className="flex flex-col">
