                  <input type="number" className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.weightKg || ''} onChange={e => setEditingModel({...editingModel, weightKg: parseFloat(e.target.value)})} />
                  <div className="absolute right-3 top-3 text-sm text-on-surface-variant font-medium">
                     Custo: R$ {((editingModel.weightKg || 0) * rawMaterialCostPerKg).toFixed(2)}
                  </div>
               </div>
               <div className="flex gap-2 mt-2">
                  {[8, 14, 22, 32].map(w => (
                    <button key={w} onClick={() => setEditingModel({...editingModel, weightKg: w})} className="px-3 py-1 bg-surface-variant/50 hover:bg-surface-variant rounded-lg text-xs text-on-surface-variant transition-colors">
                      {w}kg
                    </button>
                  ))}
               </div>
             </div>

             <div className="grid grid-cols-2 gap-4">
                <div>
                   <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Mão de Obra (Prod.)</label>
                   <input type="number" className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.costProduction || ''} onChange={e => setEditingModel({...editingModel, costProduction: parseFloat(e.target.value)})} />
                </div>
                {editingModel.type === VaseType.WITH_SHELL && (
                  <>
                    <div>
                      <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Custo Acab.</label>
                      <input type="number" className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.costFinishing || ''} onChange={e => setEditingModel({...editingModel, costFinishing: parseFloat(e.target.value)})} />
                    </div>
                    <div className="col-span-2">
                      <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Preço de Venda</label>
                      <input type="number" className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.priceSale || ''} onChange={e => setEditingModel({...editingModel, priceSale: parseFloat(e.target.value)})} />
                    </div>
                  </>
                )}
             </div>
           </div>
        </Modal>
      </div>
    );
  };

  const EmployeesTab = () => {
    const [isEmpModalOpen, setIsEmpModalOpen] = useState(false);
    const [editingEmp, setEditingEmp] = useState<Partial<Employee>>({ active: true });

    const handleSaveEmployee = () => {
      if (!editingEmp.name || !editingEmp.sector) return;

      if (editingEmp.id) {
        updateEmployee(editingEmp as Employee);
      } else {
        addEmployee({ ...editingEmp, id: uuidv4() } as Employee);
      }
      setIsEmpModalOpen(false);
      setEditingEmp({ active: true });
    };

    const toggleStatus = (emp: Employee) => {
      updateEmployee({ ...emp, active: !emp.active });
    };

    return (
       <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
         <div className="flex justify-between items-center px-1">
          <h2 className="text-2xl font-normal text-on-background">Funcionários</h2>
          <Button onClick={() => { setEditingEmp({ active: true, sector: Sector.PRODUCTION }); setIsEmpModalOpen(true); }} size="sm" className="rounded-full">
            <Plus className="mr-1 w-4 h-4" /> Novo
          </Button>
        </div>

        <div className="grid gap-3">
          {employees.map(emp => (
            <div key={emp.id} className="bg-surface p-4 rounded-2xl shadow-sm border border-outline-variant/30 flex items-center justify-between group">
               <div className="flex items-center gap-4">
                  <div className={`w-12 h-12 rounded-full flex items-center justify-center font-bold text-lg uppercase transition-colors ${emp.active ? 'bg-primary-container text-on-primary-container' : 'bg-surface-variant text-on-surface-variant'}`}>
                    {emp.name.slice(0, 2)}
                  </div>
                  <div>
                    <h3 className={`font-medium text-lg ${emp.active ? 'text-on-surface' : 'text-on-surface-variant'}`}>{emp.name}</h3>
                    <div className="flex items-center gap-2">
                       <span className="text-xs text-on-surface-variant">{emp.sector}</span>
                       {!emp.active && <span className="text-xs bg-error-container text-on-error-container px-2 py-0.5 rounded-full font-bold">Inativo</span>}
                    </div>
                  </div>
               </div>

               <div className="flex items-center gap-2">
                 <button onClick={() => { setEditingEmp(emp); setIsEmpModalOpen(true); }} className="p-2 text-on-surface-variant hover:text-primary hover:bg-primary-container/20 rounded-full transition-colors">
                    <Pencil className="w-5 h-5" />
                 </button>
                 <button onClick={() => toggleStatus(emp)} className={`p-2 rounded-full transition-colors ${emp.active ? 'text-success hover:bg-success-container/20' : 'text-outline hover:bg-surface-variant'}`}>
                    {emp.active ? <CheckCircle2 className="w-5 h-5" /> : <XCircle className="w-5 h-5" />}
                 </button>
               </div>
            </div>
          ))}
        </div>

        <Modal isOpen={isEmpModalOpen} onClose={() => setIsEmpModalOpen(false)} title={editingEmp.id ? "Editar Funcionário" : "Novo Funcionário"} footer={
           <div className="flex gap-2 w-full justify-end">
             <Button variant="ghost" onClick={() => setIsEmpModalOpen(false)}>Cancelar</Button>
             <Button onClick={handleSaveEmployee}>Salvar</Button>
           </div>
        }>
          <div className="space-y-4 py-2">
            <div>
               <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Nome Completo</label>
               <input className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingEmp.name || ''} onChange={e => setEditingEmp({...editingEmp, name: e.target.value})} placeholder="Ex: João da Silva" />
             </div>
             <div>
               <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Setor</label>
               <select 
                  className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                  value={editingEmp.sector || Sector.PRODUCTION}
                  onChange={e => setEditingEmp({...editingEmp, sector: e.target.value as Sector})}
               >
                 {Object.values(Sector).map(s => <option key={s} value={s}>{s}</option>)}
               </select>
               <p className="text-xs text-on-surface-variant mt-2">O setor define quais telas o funcionário pode acessar e como sua produção é calculada.</p>
             </div>

             <div className="flex items-center gap-3 pt-2">
                <input 
                  type="checkbox" 
                  id="activeCheck" 
                  className="w-5 h-5 rounded border-outline text-primary focus:ring-primary"
                  checked={editingEmp.active}
                  onChange={e => setEditingEmp({...editingEmp, active: e.target.checked})}
                />
                <label htmlFor="activeCheck" className="text-on-surface font-medium">Cadastro Ativo</label>
             </div>
          </div>
        </Modal>
       </div>
    )
  };

  const PaymentsTab = () => {
    const [selectedEmpId, setSelectedEmpId] = useState<string>('');
    const [amount, setAmount] = useState<string>('');
    const [obs, setObs] = useState('');
    const [feedback, setFeedback] = useState('');

    // Date State for Payment - Default Today
    const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

    const activeEmployees = useMemo(() => employees.filter(e => e.active), [employees]);
    const selectedEmployee = activeEmployees.find(e => e.id === selectedEmpId);

    const handleRegisterPayment = () => {
       if (!selectedEmployee || !amount) return;

       const val = parseFloat(amount);
       if (isNaN(val) || val <= 0) return;

       // Use selected date (noon)
       const paymentDate = new Date(selectedDate + 'T12:00:00').getTime();

       const record: PaymentRecord = {
         id: uuidv4(),
         employeeId: selectedEmployee.id,
         employeeName: selectedEmployee.name,
         sector: selectedEmployee.sector,
         amount: val,
         date: paymentDate, // Use user selected date
         observation: obs
       };

       addPayment(record);
       setAmount('');
       setObs('');
       setFeedback('Pagamento registrado!');
       setTimeout(() => setFeedback(''), 3000);
    };

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <h2 className="text-2xl font-normal text-on-background px-1">Gestão de Pagamentos</h2>

        {/* Registration Card */}
        <Card className="border-primary/20 bg-surface shadow-md">
           <div className="flex items-center gap-2 mb-4 text-primary">
              <Wallet className="w-5 h-5" />
              <span className="font-bold uppercase text-xs tracking-wider">Novo Pagamento</span>
           </div>

           <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Funcionário</label>
                <select 
                  className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                  value={selectedEmpId}
                  onChange={e => setSelectedEmpId(e.target.value)}
                >
                  <option value="">Selecione...</option>
                  {activeEmployees.map(e => (
                    <option key={e.id} value={e.id}>{e.name} - {e.sector}</option>
                  ))}
                </select>
              </div>

              {selectedEmployee && (
                 <div className="flex items-center gap-2 px-1">
                    <span className="text-sm text-on-surface-variant">Setor:</span>
                    <Badge color="blue">{selectedEmployee.sector}</Badge>
                 </div>
              )}

              <div>
                 <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block flex items-center gap-2">
                    <CalendarIcon className="w-3 h-3" /> Data
                 </label>
                 <input 
                   type="date" 
                   className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                   value={selectedDate}
                   onChange={(e) => setSelectedDate(e.target.value)}
                   required
                 />
              </div>

              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Valor (R$)</label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface-variant font-bold">R$</span>
                  <input 
                    type="number" 
                    className="w-full pl-12 pr-4 py-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold"
                    value={amount}
                    onChange={e => setAmount(e.target.value)}
                    placeholder="0.00"
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Observação (Opcional)</label>
                <input 
                   className="w-full p-3 bg-surface-variant/30 border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                   value={obs}
                   onChange={e => setObs(e.target.value)}
                   placeholder="Ex: Adiantamento, Vale, Salário..."
                />
              </div>

              <Button onClick={handleRegisterPayment} className="w-full h-12 text-base shadow-lg" disabled={!selectedEmployee || !amount}>
                 Registrar Pagamento
              </Button>
              {feedback && <p className="text-success text-center font-bold text-sm">{feedback}</p>}
           </div>
        </Card>

        {/* History List */}
        <div>
           <h3 className="font-bold text-on-surface mb-3 px-1">Histórico Recente</h3>
           <div className="space-y-3">
              {payments.length === 0 ? (
                 <div className="text-center py-8 text-on-surface-variant bg-surface-variant/30 rounded-2xl border border-outline-variant/20">
                    Nenhum pagamento registrado.
                 </div>
              ) : (
                payments.sort((a,b) => b.date - a.date).map(p => (
                   <div key={p.id} className="bg-surface p-4 rounded-2xl border border-outline-variant/30 flex justify-between items-center shadow-sm">
                      <div>
                         <p className="font-bold text-on-surface">{p.employeeName}</p>
                         <div className="flex items-center gap-2 mt-1">
                            <span className="text-xs text-on-surface-variant">{new Date(p.date).toLocaleDateString()}</span>
                            <span className="w-1 h-1 bg-outline-variant rounded-full"></span>
                            <span className="text-xs text-on-surface-variant">{p.sector}</span>
                         </div>
                         {p.observation && <p className="text-xs text-on-surface-variant italic mt-1">"{p.observation}"</p>}
                      </div>
                      <span className="text-lg font-bold text-success bg-success-container/30 px-3 py-1 rounded-lg">
                         R$ {p.amount.toFixed(2)}
                      </span>
                   </div>
                ))
              )}
           </div>
        </div>
      </div>
    );
  };

  const ConfigTab = () => {
    const [confirmReset, setConfirmReset] = useState(false);
    return (
      <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <h2 className="text-2xl font-normal text-on-background px-1">Configurações</h2>

        {/* Dark Mode Toggle */}
        <Card className="flex items-center justify-between p-5 cursor-pointer hover:bg-surface-variant/30 transition-colors" onClick={toggleTheme}>
           <div className="flex items-center gap-3">
             <div className="bg-surface-variant/50 p-2 rounded-full"><Moon className="w-5 h-5 text-on-surface-variant" /></div>
             <span className="font-medium text-on-surface">Modo Escuro</span>
           </div>
           <div className={`w-12 h-7 rounded-full p-1 transition-colors ${isDarkMode ? 'bg-primary' : 'bg-surface-variant'}`}>
              <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${isDarkMode ? 'translate-x-5' : 'translate-x-0'}`} />
           </div>
        </Card>

        {/* Raw Material Cost Config */}
        <Card className="p-5 border border-outline-variant/30">
          <div className="flex items-center gap-3 mb-3 text-primary">
            <div className="bg-primary-container p-2 rounded-full"><Scale className="w-5 h-5 text-on-primary-container" /></div>
            <h3 className="font-bold text-on-surface">Custo da Matéria-Prima</h3>
          </div>
          <div className="bg-surface-variant/30 p-4 rounded-xl border border-outline-variant/20">
             <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-2 block">Custo do Traço (por Kg)</label>
             <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface-variant font-bold">R$</span>
                <input 
                  type="number" 
                  step="0.01"
                  className="w-full pl-12 pr-4 py-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary font-bold text-lg" 
                  value={rawMaterialCostPerKg} 
                  onChange={(e) => updateRawMaterialCostPerKg(parseFloat(e.target.value))} 
                />
             </div>
             <p className="text-xs text-on-surface-variant mt-2">
               Este valor será utilizado para calcular o custo de matéria-prima dos novos vasos produzidos com base no peso.
             </p>
          </div>
        </Card>

        {/* Danger Zone */}
        <Card className="p-5 border-error/20 bg-error-container/20">
           <h3 className="font-bold text-error mb-2 flex items-center gap-2">
             <Trash className="w-4 h-4" /> Zona de Perigo
           </h3>
           {!confirmReset ? (
              <Button variant="danger" className="w-full bg-surface border border-error/30 text-error hover:bg-error-container shadow-none" onClick={() => setConfirmReset(true)}>Resetar Dados do Sistema</Button>
           ) : (
             <div className="flex gap-2">
               <Button variant="ghost" onClick={() => setConfirmReset(false)} className="flex-1">Cancelar</Button>
               <Button variant="danger" onClick={() => { resetData(); setConfirmReset(false); }} className="flex-1">Confirmar Reset</Button>
             </div>
           )}
        </Card>

        <Button variant="outline" className="w-full mt-4 text-on-surface-variant border-outline" onClick={logout}>
          <LogOut className="mr-2 h-4 w-4" /> Encerrar Sessão
        </Button>
      </div>
    );
  };

  // --- Main Layout ---

  const tabs = [
    { Icon: LayoutDashboard, label: 'Dash' },
    { Icon: BoxIcon, label: 'Modelos' },
    { Icon: Users, label: 'Func.' },
    { Icon: DollarSign, label: 'Pag.' },
    { Icon: Settings, label: 'Config' },
  ];

  return (
    <div className="h-screen flex flex-col bg-background">
      {/* Top Bar */}
      <div className="bg-surface p-4 shadow-sm z-10 flex justify-between items-center px-6 border-b border-outline-variant/10">
         <h1 className="text-xl font-medium text-on-surface">Painel Supervisor</h1>
         <div className="w-8 h-8 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container font-bold text-xs">SV</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 pb-24">
        {activeTab === 0 && <DashboardTab />}
        {activeTab === 1 && <ModelsTab />}
        {activeTab === 2 && <EmployeesTab />}
        {activeTab === 3 && <PaymentsTab />}
        {activeTab === 4 && <ConfigTab />}
      </div>

      {/* MD3 Bottom Navigation Bar */}
      <div className="bg-surface border-t border-outline-variant/20 flex justify-around p-2 pb-6 shadow-md z-20">
        {tabs.map((tab, idx) => {
          const isActive = activeTab === idx;
          return (
            <button 
              key={idx}
              onClick={() => setActiveTab(idx)}
              className="flex flex-col items-center justify-center w-full gap-1 group"
            >
              <div className={`px-5 py-1.5 rounded-full transition-all duration-300 ${isActive ? 'bg-primary-container' : 'bg-transparent group-hover:bg-surface-variant/50'}`}>
                <tab.Icon size={24} className={`transition-colors ${isActive ? 'text-on-primary-container' : 'text-on-surface-variant'}`} />
              </div>
              <span className={`text-[10px] font-medium transition-colors ${isActive ? 'text-on-surface' : 'text-on-surface-variant'}`}>
                {tab.label}
              </span>
            </button>
          )
        })}
      </div>
    </div>
  );
};

export default SupervisorDashboard;

export enum Sector {
  PRODUCTION = 'Produção',
  FINISHING = 'Acabamento',
  PAINTING = 'Pintura',
  SUPERVISOR = 'Supervisor',
}

export enum VaseType {
  WITH_SHELL = 'Com Casca',
  WITHOUT_SHELL = 'Sem Casca',
}

export enum ItemStatus {
  DRAFT = 'Rascunho', // Local UI state mostly, but good to have
  PRODUCED = 'Produzido',
  STOCK_NO_SHELL = 'Estoque (Sem Casca)',
  AWAITING_FINISHING = 'Aguardando Acabamento',
  AWAITING_PAINTING = 'Aguardando Pintura',
  FINISHED = 'Finalizado',
}

export interface VaseModel {
  id: string;
  name: string;
  type: VaseType;
  weightKg: number; // New field for raw material calculation
  costProduction: number; // Labor cost for molding
  costFinishing?: number; // Only With Shell
  priceSale?: number; // Only With Shell
  // Commission is calculated dynamically (10% of sale price)
}

export interface Employee {
  id: string;
  name: string;
  sector: Sector | 'General';
  active: boolean;
}

export interface PaymentRecord {
  id: string;
  employeeId: string;
  employeeName: string;
  sector: Sector | 'General';
  amount: number;
  date: number; // Timestamp
  observation?: string;
}

export interface ProductionItem {
  id: string;
  modelId: string;
  modelName: string; // Denormalized for easier display if model is deleted
  type: VaseType;
  status: ItemStatus;
  createdAt: number; // Timestamp
  updatedAt: number; // Timestamp

  // Worker Tracking
  producedBy: string; // Employee ID
  finishedBy?: string; // Employee ID
  paintedBy?: string; // Employee ID

  // Value Tracking (Frozen at moment of execution)
  productionValue: number; // How much the producer earned (Labor)
  rawMaterialCost: number; // Cost of raw material (weight * rate) at time of production
  finishingValue?: number; // How much the finisher earned
  paintingValue?: number;  // How much the painter earned
}

// --- DRAFT SYSTEM TYPES ---
export type DraftType = 'PRODUCTION' | 'FINISHING' | 'PAINTING';

export interface DraftItemContent {
  modelId: string;
  quantity: number;
}

export interface Draft {
  id: string;
  type: DraftType;
  sector: Sector;
  userId: string;
  selectedDate: number; // The date selected by the user
  createdAt: number; // System timestamp

  // Data payload depends on type
  // Production: list of models and quantities
  productionData?: DraftItemContent[]; 

  // Processing: list of existing ProductionItem IDs
  processingIds?: string[]; 
}

export interface AppState {
  isDarkMode: boolean;
  supervisorPassword: string; // In real app, hash this.
  currentUser: Employee | null;
  currentSector: Sector | null;

  // Configs
  rawMaterialCostPerKg: number; // Default 0.26

  employees: Employee[];
  vaseModels: VaseModel[];
  productionItems: ProductionItem[];
  payments: PaymentRecord[];
  drafts: Draft[]; // New Draft Store

  // Actions
  toggleTheme: () => void;
  setSector: (sector: Sector | null) => void;
  loginUser: (user: Employee) => void;
  logout: () => void;

  // Core Actions
  addProductionItems: (items: ProductionItem[]) => void;
  processStageItems: (itemIds: string[], workerId: string, stage: 'finishing' | 'painting', timestamp: number) => void;

  // Draft Actions
  addDraft: (draft: Draft) => void;
  removeDraft: (id: string) => void;
  confirmDraft: (draftId: string) => void;

  // Supervisor Actions
  updateSupervisorPassword: (pass: string) => void;
  updateRawMaterialCostPerKg: (value: number) => void;
  addVaseModel: (model: VaseModel) => void;
  updateVaseModel: (model: VaseModel) => void;
  deleteVaseModel: (id: string) => void;
  addEmployee: (emp: Employee) => void;
  updateEmployee: (emp: Employee) => void;
  addPayment: (payment: PaymentRecord) => void;
  resetData: () => void;
}

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { AppState, ItemStatus, Sector, VaseType, ProductionItem } from './types';
import { INITIAL_EMPLOYEES, INITIAL_VASES, DEFAULT_SUPERVISOR_PASS } from './constants';
import { v4 as uuidv4 } from 'uuid';

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      rawMaterialCostPerKg: 0.26, // Default per requirement

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => set({ currentUser: user }),

      logout: () => set({ currentUser: null, currentSector: null }),

      addProductionItems: (items) => set((state) => {
        // Hydrate items with current production costs from models
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            // Calculate Raw Material Cost Snapshot: Weight * Current Rate
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });
        return { productionItems: [...state.productionItems, ...hydratedItems] };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        // Use the passed timestamp instead of Date.now()
        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            if (stage === 'finishing') {
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: model?.costFinishing || 0
              };
            }

            if (stage === 'painting') {
               // Calculate 10% commission
               const salePrice = model?.priceSale || 0;
               const commission = salePrice * 0.10;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });
        return { productionItems: updatedItems };
      }),

      // --- DRAFT ACTIONS ---

      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        // Logic based on Draft Type
        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          draft.productionData.forEach(({ modelId, quantity }) => {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {
                newItems.push({
                  id: uuidv4(),
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate, // Use Draft Date
                  updatedAt: draft.selectedDate, // Use Draft Date
                  producedBy: draft.userId,
                  productionValue: 0, // Placeholder, calculated in addProductionItems
                  rawMaterialCost: 0 // Placeholder
                });
               }
            }
          });

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        // Remove draft after processing
        get().removeDraft(draftId);
      },

      // --- SUPERVISOR ACTIONS ---

      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set({ rawMaterialCostPerKg: value }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),

      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),

      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),

      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),

      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),

      addPayment: (payment) => set((state) => ({ payments: [payment, ...state.payments] })),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        drafts: []
      }),
    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem, Draft, DraftItemContent } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, DollarSign, Wallet, Calendar, FileText, Trash2, Edit, Send } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import HistoryModal from '../components/HistoryModal';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addDraft, removeDraft, confirmDraft, drafts, currentUser, productionItems, payments, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Date State - Default to Today "YYYY-MM-DD"
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => 
    drafts.filter(d => d.type === 'PRODUCTION' && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt),
  [drafts, currentUser]);

  // 1. All items produced by THIS user (All Time)
  const myAllTimeProduction = useMemo(() => 
    productionItems.filter(p => p.producedBy === currentUser?.id),
  [productionItems, currentUser]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysProduction = myAllTimeProduction.filter(p => 
    new Date(p.createdAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysProduction.length;
  const dailyEarnings = myTodaysProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const handleSaveAsDraft = () => {
    if (draftItems.length === 0 || !currentUser) return;

    // Create timestamp from selected date
    const productionDate = new Date(selectedDate + 'T12:00:00').getTime();

    const productionData: DraftItemContent[] = draftItems.map(d => ({
       modelId: d.model.id,
       quantity: d.quantity
    }));

    const newDraft: Draft = {
       id: uuidv4(),
       type: 'PRODUCTION',
       sector: currentUser.sector as any,
       userId: currentUser.id,
       selectedDate: productionDate,
       createdAt: Date.now(),
       productionData: productionData
    };

    addDraft(newDraft);

    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback('Rascunho salvo!');
    setTimeout(() => setFeedback(null), 2000);
  };

  const handleEditDraft = (draft: Draft) => {
    if (!draft.productionData) return;

    // Reconstruct draftItems
    const reconstructed: {model: VaseModel, quantity: number}[] = [];
    draft.productionData.forEach(item => {
      const model = vaseModels.find(v => v.id === item.modelId);
      if (model) {
        reconstructed.push({ model, quantity: item.quantity });
      }
    });

    setDraftItems(reconstructed);
    setSelectedDate(new Date(draft.selectedDate).toISOString().split('T')[0]);
    // Determine type from first item (assuming draft is consistent)
    if (reconstructed.length > 0) {
      setSelectedType(reconstructed[0].model.type);
    }

    removeDraft(draft.id); // Remove old draft to "update" it
    setIsModalOpen(true);
  };

  const handleConfirmDraft = (draftId: string) => {
    confirmDraft(draftId);
    setFeedback('Produção confirmada!');
    setTimeout(() => setFeedback(null), 2000);
  };

  return (
    <div className="pb-32 bg-background min-h-screen">
      {/* Top App Bar area */}
      <div className="bg-surface p-4 sticky top-0 z-10 shadow-sm flex items-center justify-between border-b border-outline-variant/10">
         <Button variant="ghost" onClick={logout} className="text-on-surface-variant">
            <ArrowLeft className="w-6 h-6" />
