import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus, Draft } from '../types';
import { Button, Card, Modal } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, DollarSign, Hammer, Wallet, ClipboardList, Calendar, FileText, Edit, Trash2, Send } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';
import { v4 as uuidv4 } from 'uuid';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, addDraft, removeDraft, confirmDraft, drafts, currentUser, logout, vaseModels, payments } = useStore();
