export const exportProductionReport = (items: ProductionItem[], context: string) => {
  const data = items.map(item => ({
    Data: new Date(item.updatedAt).toLocaleDateString('pt-BR'),
    Hora: new Date(item.updatedAt).toLocaleTimeString('pt-BR'),
    Modelo: item.modelName,
    Tipo: item.type,
    Status: item.status,
    Valor_Producao: (item.productionValue || 0).toFixed(2).replace('.', ','),
    Valor_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ','),
    Valor_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ','),
    ID_Registro: item.id
  }));

  const csv = convertToCSV(data);
  downloadCSV(csv, `relatorio_producao_${context}_${new Date().toISOString().split('T')[0]}.csv`);
};

export const exportPaymentReport = (payments: PaymentRecord[], context: string) => {
  const data = payments.map(p => ({
