// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'outline' | 'fab';
  size?: 'sm' | 'md' | 'lg' | 'xl';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', size = 'md', isLoading, className, ...props 
}) => {
  const baseStyles = "font-medium transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center gap-2 relative overflow-hidden";

  const variants = {
    // Removed transparency modifiers (/80, /10, etc) and replaced with solid colors or explicit hover states
    primary: "bg-primary text-on-primary hover:brightness-110 shadow-md hover:shadow-lg rounded-full",
    secondary: "bg-secondary-container text-on-secondary-container hover:brightness-95 rounded-full",
    danger: "bg-error text-on-error hover:brightness-110 shadow-md hover:shadow-lg rounded-full",
    ghost: "bg-transparent text-on-surface hover:bg-surface-variant rounded-full",
    outline: "border border-outline text-primary hover:bg-primary-container hover:text-on-primary-container bg-transparent rounded-full",
    fab: "bg-primary-container text-on-primary-container shadow-lg hover:shadow-xl rounded-2xl border border-primary/10 hover:brightness-105"
  };

  const sizes = {
    sm: "h-8 px-4 text-sm",
    md: "h-10 px-6 text-sm",
    lg: "h-14 px-8 text-base", 
    xl: "h-16 px-8 text-lg font-bold",
  };

  return (
    <button className={cn(baseStyles, variants[variant], sizes[size], className)} {...props}>
      {isLoading && <Loader2 className="w-5 h-5 animate-spin" />}
      {children}
    </button>
  );
};

// --- Card ---
export const Card: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ children, className, ...props }) => {
  // MD3 Elevated Card: Surface color + shadow, NO transparency
  return (
    <div className={cn("bg-surface text-on-surface rounded-2xl shadow-sm border border-outline-variant p-5", className)} {...props}>
      {children}
    </div>
  );
};

// --- Modal ---
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  footer?: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, footer }) => {
  if (!isOpen) return null;
  return (
    // Backdrop can be transparent (standard UX), but modal content must be solid
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 animate-in fade-in duration-200">
      <div className="bg-surface text-on-surface rounded-[28px] w-full max-w-sm md:max-w-md flex flex-col shadow-2xl animate-in zoom-in-95 duration-200 border border-outline-variant">
        <div className="flex justify-between items-center px-6 pt-6 pb-2">
          <h2 className="text-2xl font-normal text-on-surface">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-surface-variant rounded-full transition-colors text-on-surface-variant">
            <X className="w-6 h-6" />
          </button>
        </div>
        <div className="px-6 py-4 overflow-y-auto max-h-[60vh] text-on-surface-variant">
          {children}
        </div>
        {footer && (
          <div className="px-6 pb-6 pt-2 flex justify-end gap-2">
            {footer}
          </div>
        )}
      </div>
    </div>
  );
};

// --- Badge ---
export const Badge: React.FC<{ children: React.ReactNode, color?: 'blue' | 'green' | 'yellow' | 'red' }> = ({ children, color = 'blue' }) => {
  const colors = {
    blue: 'bg-primary-container text-on-primary-container',
    green: 'bg-success-container text-on-success-container',
    yellow: 'bg-secondary-container text-on-secondary-container',
    red: 'bg-error-container text-on-error-container',
  };
  return (
    <span className={cn("px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide", colors[color])}>
      {children}
    </span>
  );
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, ItemStatus, ProductionItem, Draft, DraftItemContent } from '../types';
import { Button, Card, Badge, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, DollarSign, Wallet, Calendar, FileText, Trash2, Edit, Send } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import HistoryModal from '../components/HistoryModal';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addDraft, removeDraft, confirmDraft, drafts, currentUser, productionItems, payments, logout } = useStore();
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedType, setSelectedType] = useState<VaseType | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Date State - Default to Today "YYYY-MM-DD"
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => 
    drafts.filter(d => d.type === 'PRODUCTION' && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt),
  [drafts, currentUser]);

  // 1. All items produced by THIS user (All Time)
  const myAllTimeProduction = useMemo(() => 
    productionItems.filter(p => p.producedBy === currentUser?.id),
  [productionItems, currentUser]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysProduction = myAllTimeProduction.filter(p => 
    new Date(p.createdAt).toDateString() === today
  );
  const dailyTotalQty = myTodaysProduction.length;
  const dailyEarnings = myTodaysProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);

  // 4. Global Balance Calculation
  const totalProducedValue = myAllTimeProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  const availableModels = useMemo(() => {
    if (!selectedType) return [];
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const handleSaveAsDraft = () => {
    if (draftItems.length === 0 || !currentUser) return;

    // Create timestamp from selected date
    const productionDate = new Date(selectedDate + 'T12:00:00').getTime();

    const productionData: DraftItemContent[] = draftItems.map(d => ({
       modelId: d.model.id,
       quantity: d.quantity
    }));

    const newDraft: Draft = {
       id: uuidv4(),
       type: 'PRODUCTION',
       sector: currentUser.sector as any,
       userId: currentUser.id,
       selectedDate: productionDate,
       createdAt: Date.now(),
       productionData: productionData
    };

    addDraft(newDraft);

    setDraftItems([]);
    setIsModalOpen(false);
    setSelectedType(null);
    setFeedback('Rascunho salvo!');
    setTimeout(() => setFeedback(null), 2000);
  };

  const handleEditDraft = (draft: Draft) => {
    if (!draft.productionData) return;

    // Reconstruct draftItems
    const reconstructed: {model: VaseModel, quantity: number}[] = [];
    draft.productionData.forEach(item => {
      const model = vaseModels.find(v => v.id === item.modelId);
      if (model) {
        reconstructed.push({ model, quantity: item.quantity });
      }
    });

    setDraftItems(reconstructed);
    setSelectedDate(new Date(draft.selectedDate).toISOString().split('T')[0]);
    // Determine type from first item (assuming draft is consistent)
    if (reconstructed.length > 0) {
      setSelectedType(reconstructed[0].model.type);
    }

    removeDraft(draft.id); // Remove old draft to "update" it
    setIsModalOpen(true);
  };

  const handleConfirmDraft = (draftId: string) => {
    confirmDraft(draftId);
    setFeedback('Produção confirmada!');
    setTimeout(() => setFeedback(null), 2000);
  };

  return (
    <div className="pb-32 bg-background min-h-screen">
      {/* Top App Bar area */}
      <div className="bg-surface p-4 sticky top-0 z-10 shadow-sm flex items-center justify-between border-b border-outline-variant">
         <Button variant="ghost" onClick={logout} className="text-on-surface-variant">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <h1 className="text-xl font-medium text-on-surface">Setor de Produção</h1>
         <div className="w-10"></div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">
        {/* Financial Dashboard - Solid Background */}
        <div className="bg-primary rounded-3xl p-6 text-on-primary shadow-lg">
          <div className="flex justify-between items-start mb-6">
             <div>
               <p className="text-on-primary font-medium opacity-90">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Seu desempenho</h2>
             </div>
             <div className="bg-primary-container p-2 rounded-xl text-on-primary-container">
               <TrendingUp className="w-5 h-5" />
             </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* Card 1: Daily Production - Solid Primary Container */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-primary-container text-on-primary-container rounded-2xl p-4 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-primary outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <ClipboardList className="w-4 h-4" />
                   <span className="text-sm font-medium">Hoje</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs opacity-90 mt-1 flex items-center font-medium">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Current Balance - Solid Primary Container */}
             <button 
                onClick={() => setHistoryMode('financial')} 
                className="bg-primary-container text-on-primary-container rounded-2xl p-4 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-primary outline-none"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs opacity-90 mt-1 flex items-center font-medium">
                  Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* --- DRAFTS SECTION - Solid Backgrounds --- */}
        {myDrafts.length > 0 && (
          <div className="animate-in slide-in-from-bottom-2 duration-500">
             <div className="flex items-center gap-2 mb-3 px-2">
                <FileText className="w-5 h-5 text-secondary" />
                <h3 className="text-lg font-medium text-on-background">Rascunhos Pendentes</h3>
                <span className="bg-secondary-container text-on-secondary-container text-xs font-bold px-2 py-0.5 rounded-full">{myDrafts.length}</span>
             </div>

             <div className="space-y-3">
               {myDrafts.map(draft => {
                 const totalQty = draft.productionData?.reduce((a,b) => a + b.quantity, 0) || 0;
                 const draftDate = new Date(draft.selectedDate).toLocaleDateString();

                 return (
                   <div key={draft.id} className="bg-surface border border-outline-variant p-4 rounded-2xl relative shadow-sm">
                      <div className="flex justify-between items-start mb-3">
                         <div>
                            <div className="flex items-center gap-2">
                               <p className="font-bold text-on-surface">Produção de {draftDate}</p>
                            </div>
                            <p className="text-xs text-on-surface-variant mt-0.5">Criado em {new Date(draft.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                         </div>
                         <div className="flex items-center gap-1">
                            <button onClick={() => handleEditDraft(draft)} className="p-2 text-on-surface-variant hover:text-primary hover:bg-primary-container rounded-full transition-colors" title="Editar">
                               <Edit className="w-5 h-5" />
                            </button>
                            <button onClick={() => removeDraft(draft.id)} className="p-2 text-on-surface-variant hover:text-error hover:bg-error-container rounded-full transition-colors" title="Excluir">
                               <Trash2 className="w-5 h-5" />
                            </button>
                         </div>
                      </div>

                      <div className="flex flex-wrap gap-2 mb-4">
                         {draft.productionData?.map((item, idx) => {
                           const model = vaseModels.find(v => v.id === item.modelId);
                           if (!model) return null;
                           return (
                             <span key={idx} className="text-xs bg-surface-variant text-on-surface-variant font-medium px-2 py-1 rounded-md border border-outline-variant">
                               {item.quantity}x {model.name}
                             </span>
                           )
                         })}
                      </div>

                      <Button onClick={() => handleConfirmDraft(draft.id)} variant="primary" className="w-full gap-2">
                         <Send className="w-4 h-4" /> Confirmar Produção
                      </Button>
                   </div>
                 );
               })}
             </div>
          </div>
        )}

      </div>

      {/* Floating Action Button */}
      <div className="fixed bottom-6 right-6 z-20">
        <Button 
           variant="fab" 
           size="lg" 
           onClick={() => setIsModalOpen(true)}
           className="h-16 pl-6 pr-8 rounded-[20px]"
        >
          <Plus className="w-6 h-6 mr-2" />
          <span className="text-lg font-medium">Registrar Produção</span>
        </Button>
      </div>

      {/* Snackbar Feedback */}
      {feedback && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom fade-in duration-300 w-full px-4 flex justify-center">
           <div className="bg-on-surface text-surface px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 border border-outline-variant">
              <Check className="w-5 h-5 text-success" />
              <span className="font-medium">{feedback}</span>
           </div>
        </div>
      )}

      {/* History Modal - Intermediate Selection for 'financial' click */}
      {historyMode === 'financial' ? (
        <Modal isOpen={true} onClose={() => setHistoryMode('none')} title="Detalhes Financeiros" footer={
          <Button variant="ghost" onClick={() => setHistoryMode('none')}>Fechar</Button>
        }>
           <div className="space-y-3 py-2">
             <button onClick={() => setHistoryMode('items')} className="w-full p-4 rounded-2xl bg-surface border border-outline-variant flex justify-between items-center hover:bg-primary-container hover:text-on-primary-container transition-colors group">
               <div className="flex items-center gap-3">
                  <div className="bg-primary-container text-on-primary-container p-2 rounded-full group-hover:bg-primary group-hover:text-on-primary transition-colors"><ClipboardList className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold">Histórico de Produção</p>
                     <p className="text-xs opacity-80">Veja tudo que você produziu</p>
                  </div>
               </div>
               <span className="font-bold text-primary group-hover:text-on-primary-container">R$ {totalProducedValue.toFixed(2)}</span>
             </button>

             <button onClick={() => setHistoryMode('payments')} className="w-full p-4 rounded-2xl bg-surface border border-outline-variant flex justify-between items-center hover:bg-success-container hover:text-on-success-container transition-colors group">
               <div className="flex items-center gap-3">
                  <div className="bg-success-container text-on-success-container p-2 rounded-full group-hover:bg-success group-hover:text-on-success transition-colors"><Wallet className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold">Pagamentos Recebidos</p>
                     <p className="text-xs opacity-80">Extrato de valores pagos</p>
                  </div>
               </div>
               <span className="font-bold text-success group-hover:text-on-success-container">R$ {totalReceivedValue.toFixed(2)}</span>
             </button>

             <div className="mt-4 pt-4 border-t border-outline-variant flex justify-between items-center">
               <span className="text-on-surface-variant font-medium">Saldo a Receber</span>
               <span className="text-xl font-bold text-on-surface">R$ {currentBalance.toFixed(2)}</span>
             </div>
           </div>
        </Modal>
      ) : (
        <HistoryModal 
          isOpen={historyMode !== 'none'}
          onClose={() => setHistoryMode('none')}
          mode={historyMode === 'items' ? 'items' : historyMode === 'payments' ? 'payments' : 'financial'}
          items={myAllTimeProduction}
          payments={myAllTimePayments}
          vaseModels={vaseModels}
          valueKey="productionValue"
          title={historyMode === 'items' ? 'Histórico de Produção' : historyMode === 'payments' ? 'Pagamentos Recebidos' : 'Extrato'}
        />
      )}

      {/* Launch Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={selectedType ? `Registrar: ${selectedType}` : "Nova Produção"}
        footer={
          draftItems.length > 0 ? (
            <div className="flex flex-col gap-4 w-full">
               <div className="bg-surface p-3 rounded-xl border border-outline-variant">
                 <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block flex items-center gap-2">
                   <Calendar className="w-3 h-3" /> Data de Produção
                 </label>
                 <input 
                   type="date" 
                   className="w-full p-2 bg-surface-variant text-on-surface border border-outline-variant rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                   value={selectedDate}
                   onChange={(e) => setSelectedDate(e.target.value)}
                   required
                 />
               </div>

               <div className="flex items-center justify-between w-full">
                  <div className="text-on-surface-variant font-medium ml-2">
                    Total: <span className="text-on-surface font-bold text-lg">{draftItems.reduce((a,b) => a + b.quantity, 0)}</span>
                  </div>
                  <div className="flex gap-2">
                    <Button variant="ghost" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
                    <Button onClick={handleSaveAsDraft} variant="secondary" className="px-6 bg-secondary-container text-on-secondary-container">
                      Salvar Rascunho
                    </Button>
                  </div>
               </div>
            </div>
          ) : undefined
        }
      >
        {!selectedType ? (
          <div className="grid grid-cols-1 gap-4 mt-2">
             <button onClick={() => setSelectedType(VaseType.WITH_SHELL)} className="group text-left p-4 rounded-2xl border border-outline-variant bg-surface hover:border-primary hover:bg-primary-container transition-all">
                <div className="text-lg font-bold text-on-surface group-hover:text-on-primary-container">Com Casca</div>
                <div className="text-sm text-on-surface-variant group-hover:text-on-primary-container/80">Acabamento Liso &rarr; Pintura</div>
             </button>
             <button onClick={() => setSelectedType(VaseType.WITHOUT_SHELL)} className="group text-left p-4 rounded-2xl border border-outline-variant bg-surface hover:border-primary hover:bg-primary-container transition-all">
                <div className="text-lg font-bold text-on-surface group-hover:text-on-primary-container">Sem Casca</div>
                <div className="text-sm text-on-surface-variant group-hover:text-on-primary-container/80">Acabamento Rústico &rarr; Estoque</div>
             </button>
          </div>
        ) : (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setSelectedType(null)} className="mb-2 pl-0 -ml-2 text-on-surface-variant">
               <ArrowLeft className="mr-2 h-4 w-4" /> Voltar para Tipos
            </Button>

            <div className="grid gap-3 max-h-[50vh] overflow-y-auto pr-1">
              {availableModels.map(model => {
                 const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
                 return (
                   <div key={model.id} className="flex items-center justify-between p-3 bg-surface border border-outline-variant rounded-xl">
                      <div className="flex-1">
                        <div className="font-medium text-on-surface">{model.name}</div>
                        <div className="text-xs text-on-success-container font-bold bg-success-container inline-block px-2 py-0.5 rounded-md mt-1">
                          Ganho: R$ {model.costProduction.toFixed(2)}
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        {inDraft > 0 && (
                          <button onClick={() => removeFromDraft(model.id)} className="w-8 h-8 rounded-full bg-surface-variant hover:bg-outline-variant text-on-surface-variant flex items-center justify-center transition-colors">
                             <Minus className="w-4 h-4" />
                          </button>
                        )}
                        <span className={`w-6 text-center font-bold ${inDraft > 0 ? 'text-primary' : 'text-on-surface-variant'}`}>
                           {inDraft}
                        </span>
                        <button onClick={() => addToDraft(model)} className="w-8 h-8 rounded-full bg-primary-container hover:bg-primary text-on-primary-container hover:text-on-primary flex items-center justify-center transition-colors">
                           <Plus className="w-4 h-4" />
                        </button>
                      </div>
                   </div>
                 );
              })}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default ProductionScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus, Draft } from '../types';
import { Button, Card, Modal } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, DollarSign, Hammer, Wallet, ClipboardList, Calendar, FileText, Edit, Trash2, Send } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';
import { v4 as uuidv4 } from 'uuid';

interface Props {
  stage: 'finishing' | 'painting';
}

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, addDraft, removeDraft, confirmDraft, drafts, currentUser, logout, vaseModels, payments } = useStore();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  // Date State for Processing Date - Default Today
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // History Modal State
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Financial Dashboard Logic ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => {
    const draftType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
    return drafts.filter(d => d.type === draftType && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt);
  }, [drafts, currentUser, stage]);

  // Filter out items that are currently in a draft to prevent double selection
  const itemsInDrafts = useMemo(() => {
     const ids = new Set<string>();
     myDrafts.forEach(d => d.processingIds?.forEach(id => ids.add(id)));
     return ids;
  }, [myDrafts]);

  // 1. All items processed by THIS user (All Time)
  const myAllTimeItems = useMemo(() => productionItems.filter(p => {
    if (stage === 'finishing') return p.finishedBy === currentUser?.id;
    if (stage === 'painting') return p.paintedBy === currentUser?.id;
    return false;
  }), [productionItems, currentUser, stage]);

  // 2. All payments received by THIS user (All Time)
  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  // 3. Stats for Today
  const myTodaysItems = myAllTimeItems.filter(p => 
     new Date(p.updatedAt).toDateString() === today
  );
