  // --- Sub-components for Tabs ---

  const DashboardTab = () => {
    const [timeRange, setTimeRange] = useState<'today' | 'week' | 'month' | 'all'>('month');

    // 1. Filter Logic
    const filteredItems = useMemo(() => {
      const now = new Date();
      let startTime = 0;

      if (timeRange === 'today') {
        startTime = new Date(now.setHours(0,0,0,0)).getTime();
      } else if (timeRange === 'week') {
        const d = new Date();
        d.setDate(d.getDate() - 7);
        startTime = d.setHours(0,0,0,0);
      } else if (timeRange === 'month') {
        const d = new Date();
        d.setDate(d.getDate() - 30);
        startTime = d.setHours(0,0,0,0);
      }

      return productionItems.filter(item => item.createdAt >= startTime);
    }, [productionItems, timeRange]);

    // 2. Financial Calculations
    const financials = useMemo(() => {
      let rawMaterial = 0;
      let laborProduction = 0;
      let laborFinishing = 0;
      let laborPainting = 0;

      filteredItems.forEach(item => {
        rawMaterial += (item.rawMaterialCost || 0);
        laborProduction += (item.productionValue || 0);
        laborFinishing += (item.finishingValue || 0);
        laborPainting += (item.paintingValue || 0);
      });

      return {
        rawMaterial,
        laborProduction,
        laborFinishing,
        laborPainting,
        total: rawMaterial + laborProduction + laborFinishing + laborPainting
      };
    }, [filteredItems]);

    // 3. Operational Calculations
    const operational = useMemo(() => {
      const produced = filteredItems.length;
      // Count items that have passed specific stages based on value presence or status
      const finished = filteredItems.filter(i => (i.finishingValue || 0) > 0 || i.status === ItemStatus.AWAITING_PAINTING || i.status === ItemStatus.FINISHED).length;
      const painted = filteredItems.filter(i => (i.paintingValue || 0) > 0 || i.status === ItemStatus.FINISHED).length;

      return { produced, finished, painted };
    }, [filteredItems]);

