// Helper to convert array of objects to CSV string
const convertToCSV = (objArray: any[]) => {
  if (!objArray || objArray.length === 0) return '';

  const array = typeof objArray !== 'object' ? JSON.parse(objArray) : objArray;
  let str = '';

  // Headers
  const headers = Object.keys(array[0]).join(',');
  str += headers + '\r\n';

  // Rows
  for (let i = 0; i < array.length; i++) {
    let line = '';
    for (const index in array[i]) {
      if (line !== '') line += ',';

      let cell = array[i][index];

      // Handle strings containing commas or quotes
      if (typeof cell === 'string') {
        cell = `"${cell.replace(/"/g, '""')}"`;
      }
      // Handle dates (if strictly numbers looking like timestamps, could format, but keeping raw for now or relying on pre-formatted objects)

      line += cell;
    }
    str += line + '\r\n';
  }
  return str;
};

// Helper to download the file
const downloadCSV = (csvContent: string, fileName: string) => {
  // Add Byte Order Mark (BOM) for Excel UTF-8 compatibility
  const bom = '\uFEFF'; 
  const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');

  if (link.download !== undefined) {
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', fileName);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
};

