export const exportProductionReport = (items: ProductionItem[], context: string, sector?: Sector) => {
  const data = items.map(item => {
    // Campos base comuns a todos
    const baseFields = {
      Data: new Date(item.updatedAt).toLocaleDateString('pt-BR'),
      Hora: new Date(item.updatedAt).toLocaleTimeString('pt-BR'),
      Modelo: item.modelName,
      Tipo: item.type,
      Status: item.status,
      ID_Registro: item.id
    };

    // Filtragem de colunas por setor
    if (sector === Sector.PRODUCTION) {
      return {
        ...baseFields,
        Valor_Producao: (item.productionValue || 0).toFixed(2).replace('.', ',')
      };
    }

    if (sector === Sector.FINISHING) {
      return {
        ...baseFields,
        Valor_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ',')
      };
    }

    if (sector === Sector.PAINTING) {
      return {
        ...baseFields,
        Valor_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ',')
      };
    }

    // Caso não tenha setor específico (ou seja Supervisor), exporta tudo
    return {
      ...baseFields,
      Valor_Producao: (item.productionValue || 0).toFixed(2).replace('.', ','),
      Valor_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ','),
      Valor_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ',')
    };
  });

  const csv = convertToCSV(data);
  const sectorLabel = sector ? sector.toLowerCase().replace(/ç|ã/g, 'c') : 'geral';
  downloadCSV(csv, `relatorio_${sectorLabel}_${context}_${new Date().toISOString().split('T')[0]}.csv`);
};

export const exportPaymentReport = (payments: PaymentRecord[], context: string) => {
  const data = payments.map(p => ({
    Data: new Date(p.date).toLocaleDateString('pt-BR'),
    Funcionario: p.employeeName,
    Setor: p.sector,
    Valor: p.amount.toFixed(2).replace('.', ','),
    Observacao: p.observation || '',
    ID_Pagamento: p.id
  }));

  const csv = convertToCSV(data);
  downloadCSV(csv, `relatorio_pagamentos_${context}_${new Date().toISOString().split('T')[0]}.csv`);
};

export const exportFullSupervisorReport = (
  items: ProductionItem[], 
  payments: PaymentRecord[], 
  models: VaseModel[],
  filters: string
) => {
  // We can create a consolidated summary or separate logic. 
  // For supervisor, let's export the raw filtered production list with extra details.

  const data = items.map(item => {
    // Find model to get weight/cost details if needed, though item has snapshots
    return {
      Data_Criacao: new Date(item.createdAt).toLocaleDateString('pt-BR'),
      Data_Atualizacao: new Date(item.updatedAt).toLocaleDateString('pt-BR'),
      Modelo: item.modelName,
      Tipo: item.type,
      Status: item.status,
      Produtor_ID: item.producedBy,
      Acabador_ID: item.finishedBy || '-',
      Pintor_ID: item.paintedBy || '-',
      Custo_Materia_Prima: item.rawMaterialCost.toFixed(2).replace('.', ','),
      Custo_Mao_Obra: item.productionValue.toFixed(2).replace('.', ','),
      Custo_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ','),
      Custo_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ','),
      Total_Custo: (item.rawMaterialCost + item.productionValue + (item.finishingValue||0) + (item.paintingValue||0)).toFixed(2).replace('.', ',')
    };
  });

  const csv = convertToCSV(data);
  downloadCSV(csv, `relatorio_geral_supervisor_${filters}_${new Date().toISOString().split('T')[0]}.csv`);
};

import React, { useMemo } from 'react';
import { Modal, Badge, Button } from './UI';
import { ProductionItem, VaseModel, PaymentRecord, Sector } from '../types';
import { Calendar, DollarSign, Box, Wallet, Download } from 'lucide-react';
import { exportProductionReport, exportPaymentReport } from '../utils/csvHelper';

interface HistoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  mode: 'items' | 'financial' | 'payments';
  items: ProductionItem[]; // Production items
  payments?: PaymentRecord[]; // Payment records
  vaseModels: VaseModel[];
  valueKey: 'productionValue' | 'finishingValue' | 'paintingValue';
  title: string;
}

const HistoryModal: React.FC<HistoryModalProps> = ({ 
  isOpen, onClose, mode, items, payments = [], vaseModels, valueKey, title 
}) => {

  // Sort items by date descending
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => b.updatedAt - a.updatedAt);
  }, [items]);

  // Sort payments by date descending
  const sortedPayments = useMemo(() => {
    return [...payments].sort((a, b) => b.date - a.date);
  }, [payments]);

  // Calculations
  const totalProduction = items.reduce((acc, curr) => acc + (curr[valueKey] || 0), 0);
  const totalPaid = payments.reduce((acc, curr) => acc + curr.amount, 0);

  // Group for financial view (Daily Production Summary)
  const financialData = useMemo(() => {
    const groups: Record<string, { date: string, count: number, total: number }> = {};

    sortedItems.forEach(item => {
      const date = new Date(item.updatedAt).toLocaleDateString('pt-BR');
      if (!groups[date]) {
        groups[date] = { date, count: 0, total: 0 };
      }
      groups[date].count += 1;
      groups[date].total += (item[valueKey] || 0);
    });

    return Object.values(groups).sort((a, b) => {
      const [d1, m1, y1] = a.date.split('/').map(Number);
      const [d2, m2, y2] = b.date.split('/').map(Number);
      return new Date(y2, m2 - 1, d2).getTime() - new Date(y1, m1 - 1, d1).getTime();
    });
  }, [sortedItems, valueKey]);

  // Determine Sector from ValueKey to restrict export
  const getSectorFromKey = (): Sector | undefined => {
    if (valueKey === 'productionValue') return Sector.PRODUCTION;
    if (valueKey === 'finishingValue') return Sector.FINISHING;
    if (valueKey === 'paintingValue') return Sector.PAINTING;
    return undefined;
  };

  const currentSector = getSectorFromKey();

  const handleExport = () => {
    if (mode === 'payments') {
      exportPaymentReport(sortedPayments, 'historico_pessoal');
    } else {
      // Pass the restricted sector to the export function
      exportProductionReport(sortedItems, 'historico_pessoal', currentSector);
    }
  };

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={onClose} 
      title={title}
      footer={
        <div className="w-full flex flex-col gap-3">
           {currentSector && mode !== 'payments' && (
             <div className="text-xs text-center text-on-surface-variant bg-surface-variant/50 p-2 rounded-lg border border-outline-variant/50">
               Exportação restrita ao setor: <span className="font-bold text-primary">{currentSector.toUpperCase()}</span>
             </div>
           )}
           <div className="flex justify-end w-full">
             <Button variant="outline" size="sm" onClick={handleExport} className="gap-2 border-outline-variant bg-surface w-full sm:w-auto text-on-surface hover:bg-surface-variant">
                <Download className="w-4 h-4" /> Exportar CSV
             </Button>
           </div>
        </div>
      }
    >
      <div className="space-y-4">
        {/* Header Summary - Solid Background */}
        <div className="bg-surface-variant p-4 rounded-2xl border border-outline-variant flex justify-between items-center text-on-surface-variant">
          {mode === 'payments' ? (
             <>
                <div>
                  <p className="text-xs uppercase font-bold">Total Recebido</p>
                  <p className="text-2xl font-bold text-success">R$ {totalPaid.toFixed(2)}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs uppercase font-bold">Pagamentos</p>
                  <p className="text-xl font-medium text-on-surface">{payments.length}</p>
                </div>
             </>
          ) : (
            <>
              <div>
                 <p className="text-xs uppercase font-bold">Total Produzido</p>
                 <p className="text-2xl font-bold text-on-surface">R$ {totalProduction.toFixed(2)}</p>
              </div>
              <div className="text-right">
                 <p className="text-xs uppercase font-bold">Total Itens</p>
                 <p className="text-xl font-medium text-on-surface">{items.length}</p>
              </div>
            </>
          )}
        </div>

        <div className="relative">
          <div className="absolute inset-0 flex items-center" aria-hidden="true">
            <div className="w-full border-t border-outline-variant" />
          </div>
          <div className="relative flex justify-center">
            <span className="bg-surface px-2 text-xs text-on-surface-variant uppercase">
              {mode === 'items' && 'Detalhamento por Item'}
              {mode === 'financial' && 'Produção Diária'}
              {mode === 'payments' && 'Extrato de Pagamentos'}
            </span>
          </div>
        </div>

        {/* List Content */}
        <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-1">

          {/* MODE: ITEMS */}
          {mode === 'items' && sortedItems.map(item => {
              const model = vaseModels.find(v => v.id === item.modelId) || { name: item.modelName };
              const date = new Date(item.updatedAt);
              return (
                <div key={item.id} className="flex justify-between items-center p-3 bg-surface border border-outline-variant rounded-xl hover:bg-surface-variant transition-colors">
                  <div className="flex items-start gap-3">
                    <div className="bg-primary-container p-2 rounded-full text-on-primary-container mt-1">
                      <Box className="w-4 h-4" />
                    </div>
                    <div>
                      <p className="font-medium text-on-surface">{item.modelName}</p>
                      <p className="text-xs text-on-surface-variant">
                        {date.toLocaleDateString('pt-BR')} • {date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute:'2-digit'})}
                      </p>
                      <Badge color={item.type === 'Com Casca' ? 'blue' : 'yellow'}>{item.type}</Badge>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-success">+ R$ {(item[valueKey] || 0).toFixed(2)}</p>
                  </div>
                </div>
              );
          })}

          {/* MODE: FINANCIAL (Daily Summary) */}
          {mode === 'financial' && financialData.map((day, idx) => (
              <div key={idx} className="flex justify-between items-center p-4 bg-surface border border-outline-variant rounded-xl hover:bg-surface-variant transition-colors">
                 <div className="flex items-center gap-3">
                    <div className="bg-secondary-container p-2 rounded-full text-on-secondary-container">
                      <Calendar className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="font-bold text-on-surface">{day.date}</p>
                      <p className="text-xs text-on-surface-variant">{day.count} itens processados</p>
                    </div>
                 </div>
                 <div className="text-right">
                    <p className="text-lg font-bold text-primary">R$ {day.total.toFixed(2)}</p>
                 </div>
              </div>
          ))}

          {/* MODE: PAYMENTS */}
          {mode === 'payments' && sortedPayments.map((payment) => (
              <div key={payment.id} className="flex justify-between items-center p-4 bg-surface border border-outline-variant rounded-xl hover:bg-surface-variant transition-colors">
                 <div className="flex items-center gap-3">
                    <div className="bg-success-container p-2 rounded-full text-on-success-container">
                      <Wallet className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="font-bold text-on-surface">{new Date(payment.date).toLocaleDateString('pt-BR')}</p>
                      {payment.observation ? (
                        <p className="text-xs text-on-surface-variant italic max-w-[150px] truncate">"{payment.observation}"</p>
                      ) : (
                        <p className="text-xs text-on-surface-variant">Pagamento recebido</p>
                      )}
                    </div>
                 </div>
                 <div className="text-right">
                    <p className="text-lg font-bold text-success">- R$ {payment.amount.toFixed(2)}</p>
                 </div>
              </div>
          ))}

          {/* Empty State */}
          {((mode === 'items' && items.length === 0) || 
            (mode === 'financial' && items.length === 0) || 
            (mode === 'payments' && payments.length === 0)) && (
             <div className="text-center py-10 text-on-surface-variant">
               <p>Nenhum registro encontrado.</p>
             </div>
          )}
        </div>
      </div>
    </Modal>
  );
};

export default HistoryModal;

import React, { useState } from 'react';
import { useStore } from '../store';
import { Sector, Employee } from '../types';
import { Button, Card } from '../components/UI';
import { Factory, Brush, PaintBucket, ShieldCheck, User, ArrowLeft, KeyRound, Settings } from 'lucide-react';
import { APP_VERSION } from '../constants';

const LoginScreen: React.FC = () => {
  const { setSector, loginUser, employees, supervisorPassword } = useStore();

  const [selectedSector, setSelectedSector] = useState<Sector | null>(null);
  const [selectedUser, setSelectedUser] = useState<Employee | null>(null);
  const [inputPassword, setInputPassword] = useState('');
  const [error, setError] = useState('');

  const handleSectorSelect = (sector: Sector) => {
    setSelectedSector(sector);
  };

  const handleUserSelect = (user: Employee) => {
    if (selectedSector === Sector.SUPERVISOR) {
      setSelectedUser(user);
    } else {
      setSector(selectedSector);
      loginUser(user);
    }
  };

  const handleSupervisorLogin = () => {
    if (inputPassword === supervisorPassword) {
      if (selectedUser) {
        setSector(Sector.SUPERVISOR);
        loginUser(selectedUser);
      }
    } else {
      setError('Senha incorreta');
    }
  };

  const getSectorIcon = (s: Sector) => {
    switch(s) {
      case Sector.PRODUCTION: return <Factory className="w-8 h-8 text-on-primary-container" />;
      case Sector.FINISHING: return <Brush className="w-8 h-8 text-on-secondary-container" />;
      case Sector.PAINTING: return <PaintBucket className="w-8 h-8 text-on-tertiary-container" />;
      case Sector.SUPERVISOR: return <ShieldCheck className="w-6 h-6" />;
      default: return <Factory className="w-6 h-6" />;
    }
  };

  const getSectorStyle = (s: Sector) => {
     switch(s) {
        case Sector.PRODUCTION: return "bg-primary-container text-on-primary-container border-primary/20";
        case Sector.FINISHING: return "bg-secondary-container text-on-secondary-container border-secondary/20";
        case Sector.PAINTING: return "bg-tertiary-container text-on-tertiary-container border-tertiary/20"; // Using tertiary logic or fallback
        default: return "bg-surface text-on-surface border-outline-variant";
     }
  }

  // Step 1: Sector Selection
  if (!selectedSector) {
    return (
      <div className="min-h-screen bg-background flex flex-col items-center justify-center p-6 relative">
        <div className="w-full max-w-md flex flex-col h-full justify-center">
          <div className="mb-10 text-center">
            <h1 className="text-3xl font-bold text-on-background mb-2">Home Pots</h1>
            <p className="text-on-surface-variant">Selecione seu setor de trabalho</p>
          </div>

          <div className="flex flex-col gap-4 w-full">
            {/* Main Sectors Stack */}
            <button 
              onClick={() => handleSectorSelect(Sector.PRODUCTION)}
              className="bg-primary-container text-on-primary-container w-full p-6 rounded-2xl shadow-sm border border-primary/10 flex items-center gap-4 transition-transform active:scale-[0.98]"
            >
               <div className="bg-surface/20 p-3 rounded-xl">
                 <Factory className="w-8 h-8" />
               </div>
               <div className="text-left">
                 <h2 className="text-xl font-bold">Produção</h2>
                 <p className="text-sm opacity-80">Moldagem e Estrutura</p>
               </div>
            </button>

            <button 
              onClick={() => handleSectorSelect(Sector.FINISHING)}
              className="bg-secondary-container text-on-secondary-container w-full p-6 rounded-2xl shadow-sm border border-secondary/10 flex items-center gap-4 transition-transform active:scale-[0.98]"
            >
               <div className="bg-surface/20 p-3 rounded-xl">
                 <Brush className="w-8 h-8" />
               </div>
               <div className="text-left">
                 <h2 className="text-xl font-bold">Acabamento</h2>
                 <p className="text-sm opacity-80">Lixamento e Preparo</p>
               </div>
            </button>

            <button 
              onClick={() => handleSectorSelect(Sector.PAINTING)}
              // Using a distinct style for Painting to differentiate from Production (which uses primary)
              // If tertiary vars aren't set, fallback to surface-variant or hardcoded distinct look
              className="bg-surface-variant text-on-surface-variant w-full p-6 rounded-2xl shadow-sm border border-outline-variant/50 flex items-center gap-4 transition-transform active:scale-[0.98]"
            >
               <div className="bg-on-surface-variant/10 p-3 rounded-xl">
                 <PaintBucket className="w-8 h-8" />
               </div>
               <div className="text-left">
                 <h2 className="text-xl font-bold">Pintura</h2>
                 <p className="text-sm opacity-80">Coloração e Finalização</p>
               </div>
            </button>
          </div>

          <div className="mt-12 flex justify-center">
            <button 
              onClick={() => handleSectorSelect(Sector.SUPERVISOR)}
              className="flex items-center gap-2 text-on-surface-variant py-3 px-6 rounded-full hover:bg-surface-variant transition-colors"
            >
              <Settings className="w-5 h-5" />
              <span className="font-medium">Acesso do Supervisor</span>
            </button>
          </div>
        </div>

        {/* Version Footer */}
        <div className="absolute bottom-4 text-xs font-medium text-on-surface-variant opacity-70">
          Versão {APP_VERSION}
        </div>
      </div>
    );
  }

  // Step 2 & 3: Profile & Auth
  const sectorEmployees = employees.filter(e => e.sector === selectedSector || (selectedSector === Sector.SUPERVISOR && e.sector === Sector.SUPERVISOR));

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4 relative">
      <div className="w-full max-w-md">
        <div className="mb-6">
          <Button variant="ghost" size="sm" onClick={() => { setSelectedSector(null); setSelectedUser(null); setError(''); }}>
            <ArrowLeft className="mr-2 h-5 w-5" /> Voltar
          </Button>
        </div>

        <h2 className="text-3xl font-normal text-on-background mb-2">Identificação</h2>
        <p className="text-on-surface-variant mb-8">Quem é você em <span className="font-bold text-primary">{selectedSector}</span>?</p>

        {!selectedUser ? (
          <div className="space-y-3">
            {sectorEmployees.map(emp => (
              <div 
                key={emp.id}
                onClick={() => handleUserSelect(emp)}
                className="bg-surface p-4 rounded-2xl shadow-sm border border-outline-variant flex items-center cursor-pointer hover:bg-surface-variant active:scale-[0.98] transition-all"
              >
                <div className="w-12 h-12 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container mr-4">
                  <User className="h-6 w-6" />
                </div>
                <span className="text-lg font-medium text-on-surface">{emp.name}</span>
              </div>
            ))}
            {sectorEmployees.length === 0 && (
              <div className="text-center py-10 bg-surface rounded-2xl border border-outline-variant">
                <p className="text-on-surface-variant">Nenhum funcionário encontrado.</p>
              </div>
            )}
          </div>
        ) : (
          <Card className="flex flex-col gap-6 p-8 bg-surface border border-outline-variant shadow-lg">
            <div className="flex flex-col items-center mb-2">
               <div className="w-20 h-20 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container mb-4">
                 <ShieldCheck className="w-10 h-10" />
               </div>
               <h3 className="text-2xl font-bold text-on-surface">{selectedUser.name}</h3>
               <p className="text-on-surface-variant">Acesso Supervisor</p>
            </div>

            <div>
              <div className="relative">
                <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-on-surface-variant" />
                <input 
                  type="password"
                  className="w-full pl-12 pr-4 py-4 bg-surface border border-outline-variant rounded-xl focus:ring-2 focus:ring-primary focus:outline-none transition-all text-lg text-on-surface placeholder-on-surface-variant"
                  value={inputPassword}
                  onChange={(e) => { setInputPassword(e.target.value); setError(''); }}
                  placeholder="Senha de acesso"
                />
              </div>
              {error && <p className="text-error text-sm mt-2 ml-1">{error}</p>}
            </div>

            <Button size="lg" onClick={handleSupervisorLogin} className="w-full">
              Entrar no Painel
            </Button>

            <Button variant="ghost" onClick={() => setSelectedUser(null)} className="w-full">
              Trocar Usuário
            </Button>
          </Card>
        )}
      </div>

      {/* Version Footer */}
      <div className="absolute bottom-4 text-xs font-medium text-on-surface-variant opacity-70">
        Versão {APP_VERSION}
      </div>
    </div>
  );
};

export default LoginScreen;
